Tutor.registerIndex("hist-mid", [
{"id":"hist-m-1-01","kind":"unit","title":"역사란 무엇일까","text":"역사의 뜻과 역사를 배우는 까닭을 생각해 보고, 여러 자료를 따져 읽으며 과거를 탐구하는 방법을 익혀요. 역사의 두 가지 뜻을 구별하고 역사를 배우는 까닭을 말할 수 있어요. 역사 자료를 문자 자료와 비문자 자료로 나누고, 누가·언제·왜 남겼는지 따져 읽을 수 있어요. 같은 사건에 대한 서로 다른 해석을 근거를 들어 비교할 수 있어요. 연표·역사 지도와 …","keywords":["사실로서의 역사","기록으로서의 역사","사료","유물","유적","구술 자료","사료 비판","연표","기원전","세기"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#c0","kind":"concept","title":"역사의 두 가지 뜻","text":"\"역사\"라는 말에는 두 가지 뜻이 있어요. 뜻 · 설명 · 예 사실로서의 역사 · 과거에 실제로 있었던 모든 일 · 어느 해 어느 마을에서 실제로 일어난 홍수 기록으로서의 역사 · 과거의 일 가운데 사람(역사가)이 골라 조사하고 기록한 것 · 그 홍수를 조사해 쓴 책이나 보고서 과거에 ","keywords":["사실로서의 역사","기록으로서의 역사"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#c1","kind":"concept","title":"생활 속에서 만나는 역사","text":"역사는 교과서 안에만 있지 않아요. 우리는 날마다 역사를 만나요. 기념일: 3·1절(1919년 3·1 운동), 광복절(1945년 8월 15일 광복), 한글날(훈민정음을 널리 알린 일을 기념)처럼 과거의 일을 기억하려고 정한 날이에요. 문화유산: 궁궐, 성곽, 탑, 옛 그림처럼 조상이 남","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#c2","kind":"concept","title":"역사 자료의 종류","text":"과거를 알려 주는 모든 흔적을 역사 자료(사료)라고 해요. 역사 자료는 글자로 되어 있는지에 따라 둘로 나눠요. 종류 · 예 문자 자료 · 역사책, 왕의 명령을 적은 기록, 비석에 새긴 글, 편지, 일기, 신문 비문자 자료 · 유물(도구·그릇·장신구), 유적(집터·무덤·성터), 그림, ","keywords":["사료","유물","유적","구술 자료"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#c3","kind":"concept","title":"자료를 따져 읽기","text":"역사 자료라고 해서 모두 사실만 담고 있는 것은 아니에요. 그래서 자료를 읽을 때는 따져 읽기(사료 비판)를 해요. 누가 남겼을까? — 그 사람은 어떤 처지였을까? 사건과 어떤 관계였을까? 언제 남겼을까? — 사건이 일어난 때에 가까울수록 생생하지만, 오래 지나 쓰면 기억이 흐려지거나 ","keywords":["사료","유물","사료 비판"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#c4","kind":"concept","title":"서로 다른 해석과 토론","text":"역사에는 사실과 해석이 있어요. 사실: \"그 해에 두 나라 사이에 전쟁이 일어났다\"처럼 자료로 확인할 수 있는 일 해석: \"그 전쟁은 ○○ 때문에 일어났다\", \"그 전쟁은 백성에게 큰 고통이었다\"처럼 사실의 원인·결과·의미를 설명하는 것 같은 사실이라도 어떤 자료를 중요하게 보는지, 어","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#c5","kind":"concept","title":"역사 탐구의 도구 — 연표·지도·연대 표기","text":"연표는 사건을 일어난 순서대로 시간 줄 위에 정리한 표예요. 사건의 앞뒤와 같은 때 다른 곳에서 일어난 일을 한눈에 볼 수 있어요. 역사 지도는 나라의 영역, 사람과 물건이 오간 길, 전쟁이 벌어진 곳을 보여 줘요. 연대 표기 — 오늘날 세계에서 널리 쓰는 서기는 예수가 태어났다고 여긴","keywords":["연표","기원전","세기"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t0","kind":"term","title":"사실로서의 역사","text":"과거에 실제로 있었던 모든 일이에요.","keywords":["사실로서의 역사"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t1","kind":"term","title":"기록으로서의 역사","text":"과거의 일 가운데 역사가가 골라 조사하고 기록한 것이에요. 기록한 사람의 관점이 들어가요.","keywords":["기록으로서의 역사"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t2","kind":"term","title":"사료","text":"과거를 알려 주는 흔적, 곧 역사 자료예요. 문자 자료와 비문자 자료가 있어요.","keywords":["사료"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t3","kind":"term","title":"유물","text":"옛사람이 남긴 물건 가운데 옮길 수 있는 것이에요. 예: 토기, 칼, 장신구","keywords":["유물"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t4","kind":"term","title":"유적","text":"옛사람이 남긴 흔적 가운데 옮길 수 없는 장소예요. 예: 집터, 무덤, 성터","keywords":["유적"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t5","kind":"term","title":"구술 자료","text":"어떤 일을 직접 겪은 사람의 말을 듣고 기록한 자료예요.","keywords":["구술 자료"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t6","kind":"term","title":"사료 비판","text":"자료를 누가·언제·왜 남겼는지 살피고 다른 자료와 비교해 믿을 만한지 따지는 일이에요.","keywords":["사료 비판"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t7","kind":"term","title":"연표","text":"역사적 사건을 일어난 순서대로 시간 줄 위에 정리한 표예요.","keywords":["연표"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t8","kind":"term","title":"기원전","text":"서기를 세는 기준 해(1년)보다 앞선 시기예요. B.C.라고도 쓰고, 숫자가 클수록 더 오래전이에요.","keywords":["기원전"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#t9","kind":"term","title":"세기","text":"100년을 한 묶음으로 세는 단위예요. 1년~100년이 1세기, 1901년~2000년이 20세기예요.","keywords":["세기"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#f0","kind":"faq","title":"역사는 이미 지나간 일인데 왜 배워야 해요?","text":"지금 우리가 쓰는 말, 사는 모습, 나라의 제도는 모두 과거에서 이어져 왔어요. 역사를 알면 오늘이 왜 이런 모습인지 이해할 수 있어요. 또 과거 사람들이 어떤 선택을 했고 그 결과가 어땠는지 보면서 더 나은 판단을 하는 힘을 길러요. 자료를 따져 읽는 연습은 가짜 뉴스를 가려내는 데도 도움이 돼요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#f1","kind":"faq","title":"1900년은 왜 20세기가 아니라 19세기예요?","text":"세기는 1년부터 세기 시작해서, 1년~100년이 1세기예요. 그래서 각 세기의 마지막 해는 100, 200, … 1900처럼 00으로 끝나요. 1900년은 1801년~1900년인 19세기의 마지막 해예요. 20세기는 1901년부터 2000년까지예요.","keywords":["세기"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#f2","kind":"faq","title":"역사책마다 내용이 조금씩 다른데 어느 것을 믿어야 해요?","text":"역사책에는 쓴 사람의 관점이 들어가서 해석이 다를 수 있어요. 이럴 때는 어느 책이 더 믿을 만한 근거(자료)를 들고 있는지 살펴보세요. 여러 책을 비교하고, 확인된 사실과 해석을 구별하며 읽으면 스스로 판단할 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#m0","kind":"mistake","title":"자주 하는 실수","text":"세기를 구할 때 백의 자리까지의 수를 그대로 쓰는 실수 — 1392년은 13세기가 아니라 14세기예요(1301년~1400년). 단, 1900년처럼 00으로 끝나면 그대로 19세기예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#m1","kind":"mistake","title":"자주 하는 실수","text":"기원전과 기원후 사이의 햇수를 셀 때 두 수를 그냥 더하는 실수 — 0년이 없으므로 1을 빼요. 기원전 10년부터 기원후 10년까지는 19년이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-01#m2","kind":"mistake","title":"자주 하는 실수","text":"유물과 유적을 헷갈리는 실수 — 옮길 수 있는 물건(토기·칼)은 유물, 옮길 수 없는 장소(집터·무덤)는 유적이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-01","grade":"m2"},
{"id":"hist-m-1-02","kind":"unit","title":"선사 문화와 문명의 발생","text":"인류가 나타나 구석기·신석기 시대를 거쳐 큰 강 유역에서 문명을 이루기까지의 과정을 살펴봐요. 인류가 나타나 진화하고 세계 각지로 퍼져 나간 과정을 설명할 수 있어요. 구석기 시대와 신석기 시대의 도구와 생활 모습을 비교할 수 있어요. 문명이 생겨난 조건을 말하고, 네 문명의 특징을 비교할 수 있어요.","keywords":["선사 시대","뗀석기","간석기","신석기 혁명","움집","빗살무늬 토기","문명","쐐기 문자","갑골 문자","함무라비 법전"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#c0","kind":"concept","title":"인류의 출현과 진화","text":"인류는 아주 오랜 시간에 걸쳐 조금씩 바뀌어 왔어요. 이것을 진화라고 해요. 교과서에서는 대표적인 인류를 다음 순서로 살펴봐요. 인류 · 뜻 · 특징 오스트랄로피테쿠스 · 남쪽의 원숭이 · 약 300만~400만 년 전 아프리카. 두 발로 서서 걸었어요(직립 보행). 호모 하빌리스 · 손","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#c1","kind":"concept","title":"구석기 시대의 생활","text":"인류가 처음 도구를 만들어 쓴 때부터 약 1만 년 전까지를 구석기 시대라고 해요. 인류 역사의 대부분이 구석기 시대예요. 도구: 돌을 깨뜨리거나 떼어 내어 만든 뗀석기를 썼어요. 여러 용도로 쓴 주먹도끼, 짐승 가죽을 벗기는 긁개, 창끝에 꽂아 쓴 슴베찌르개 등이 있어요. 먹을거리: 짐","keywords":["뗀석기"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#c2","kind":"concept","title":"신석기 혁명","text":"약 1만 년 전 빙하기가 끝나 날씨가 따뜻해지자 사람들의 생활이 크게 바뀌었어요. 이때부터를 신석기 시대라고 해요. 도구: 돌을 갈아서 만든 간석기를 썼어요. 곡식 껍질을 벗기고 가루를 내는 갈돌과 갈판, 땅을 일구는 돌괭이 등이 있어요. 토기: 흙으로 빚어 구운 토기에 곡식을 저장하고","keywords":["간석기","신석기 혁명","움집"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#c3","kind":"concept","title":"만주와 한반도의 선사 문화","text":"만주와 한반도에서도 오래전부터 사람들이 살았어요. 구석기 시대 — 경기도 연천 전곡리에서 주먹도끼가 발견되었어요. 이 발견으로 동아시아에도 주먹도끼 문화가 있었다는 것이 알려졌어요. 충청남도 공주 석장리, 평양 근처의 상원 검은모루 동굴도 대표적인 구석기 유적이에요. 신석기 시대 — 이","keywords":["움집","빗살무늬 토기"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#c4","kind":"concept","title":"문명이 생겨난 조건","text":"문명은 사람들이 도시를 이루고, 문자와 청동기를 쓰고, 국가를 세워 다스리는 발달한 사회를 말해요. 최초의 문명들은 모두 큰 강 유역에서 생겨났어요. 왜 큰 강 유역일까? 물이 넉넉하고, 강물이 실어 온 흙으로 땅이 기름져 농사가 잘되었어요. 물길을 끌어오는 관개 시설을 만들고 홍수를 ","keywords":["문명"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#c5","kind":"concept","title":"네 문명의 특징 비교","text":"문명 · 강 · 시작 · 대표 특징 메소포타미아 · 티그리스강·유프라테스강 · 기원전 3500년경 수메르인의 도시 국가 · 쐐기 문자(점토판), 지구라트(신전), 60진법, 함무라비 법전 이집트 · 나일강 · 기원전 3000년경 통일 왕국 · 파라오(태양신의 아들), 피라미드·미라, 상","keywords":["문명","쐐기 문자","갑골 문자","함무라비 법전"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t0","kind":"term","title":"선사 시대","text":"문자로 된 기록이 없던 시대예요. 유물과 유적으로 생활 모습을 알아내요.","keywords":["선사 시대"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t1","kind":"term","title":"뗀석기","text":"돌을 깨뜨리거나 떼어 내어 만든 도구예요. 구석기 시대에 썼어요. 예: 주먹도끼","keywords":["뗀석기"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t2","kind":"term","title":"간석기","text":"돌을 갈아서 만든 도구예요. 신석기 시대부터 썼어요. 예: 갈돌과 갈판","keywords":["간석기"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t3","kind":"term","title":"신석기 혁명","text":"농경과 목축으로 먹을 것을 생산하게 되면서 정착 생활 등 삶 전체가 바뀐 큰 변화예요.","keywords":["신석기 혁명"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t4","kind":"term","title":"움집","text":"땅을 파고 기둥을 세운 뒤 지붕을 덮은 집이에요. 신석기 시대 사람들이 강가·바닷가에 짓고 살았어요.","keywords":["움집"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t5","kind":"term","title":"빗살무늬 토기","text":"겉면에 빗살 같은 무늬를 새긴 토기예요. 한반도 신석기 시대를 대표해요.","keywords":["빗살무늬 토기"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t6","kind":"term","title":"문명","text":"도시를 이루고 문자와 청동기를 쓰며 국가를 세워 다스리는 발달한 사회예요.","keywords":["문명"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t7","kind":"term","title":"쐐기 문자","text":"메소포타미아에서 갈대 끝 등으로 점토판에 눌러 새긴 쐐기 모양의 문자예요. 설형 문자라고도 해요.","keywords":["쐐기 문자"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t8","kind":"term","title":"갑골 문자","text":"중국 상(은) 왕조에서 점친 내용을 거북 등딱지나 짐승 뼈에 새긴 문자예요. 한자의 바탕이 되었어요.","keywords":["갑골 문자"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#t9","kind":"term","title":"함무라비 법전","text":"바빌로니아의 함무라비왕이 만든 법전이에요. 같은 죄라도 신분에 따라 벌이 달랐어요.","keywords":["함무라비 법전"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#f0","kind":"faq","title":"구석기와 신석기는 어떻게 구별해요?","text":"가장 쉬운 단서는 도구예요. 돌을 깨뜨려 만든 뗀석기는 구석기, 돌을 갈아 만든 간석기는 신석기예요. 생활로도 구별해요. 구석기는 사냥·채집과 이동 생활, 신석기는 농경·목축과 정착 생활(움집), 토기가 특징이에요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#f1","kind":"faq","title":"왜 문명은 모두 강가에서 생겼어요?","text":"강가는 물이 넉넉하고 강물이 실어 온 흙으로 땅이 기름져 농사가 잘되었어요. 곡식이 많이 나자 남는 곡식이 생기고, 사람이 많이 모여 도시가 되었지요. 또 홍수를 막고 물길을 내는 큰일을 함께하면서 사람들을 이끄는 지배자와 국가가 생겨났어요.","keywords":["문명"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#f2","kind":"faq","title":"인더스 문자는 왜 아직 못 읽어요?","text":"인더스 문명의 문자는 주로 도장(인장)에 짧게 새겨져 남아 있어요. 글자 수가 적고, 같은 내용을 다른 문자로 함께 적은 자료도 발견되지 않아서 아직 해독하지 못했어요. 이집트 상형 문자는 같은 내용을 세 가지 문자로 새긴 로제타석 덕분에 해독할 수 있었어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#m0","kind":"mistake","title":"자주 하는 실수","text":"뗀석기와 간석기를 헷갈리는 실수 — 깨뜨려 만든 뗀석기는 구석기, 갈아 만든 간석기는 신석기예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#m1","kind":"mistake","title":"자주 하는 실수","text":"빗살무늬 토기를 구석기 유물로 아는 실수 — 토기는 신석기 시대부터 만들었어요. 구석기의 대표 유물은 주먹도끼예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-02#m2","kind":"mistake","title":"자주 하는 실수","text":"네 문명의 문자를 섞는 실수 — 메소포타미아는 쐐기 문자, 이집트는 상형 문자, 중국은 갑골 문자예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-02","grade":"m2"},
{"id":"hist-m-1-03","kind":"unit","title":"서아시아와 지중해의 고대 세계","text":"페르시아 제국과 그리스·로마의 서로 다른 정치 모습을 비교하고, 그 속에서 자라난 종교와 문화를 알아봐요. 페르시아 제국이 넓은 영토를 다스린 방법을 설명할 수 있어요. 아테네 민주 정치의 모습과 한계를 말할 수 있어요. 알렉산드로스 제국과 헬레니즘 문화의 특징을 설명할 수 있어요. 로마가 공화정에서 제정으로 바뀐 과정과 로마 문화·크리스트교의 성립을 설…","keywords":["왕의 길","조로아스터교","폴리스","도편 추방제","직접 민주 정치","헬레니즘 문화","공화정","제정","만민법","밀라노 칙령"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#c0","kind":"concept","title":"페르시아 제국의 통치와 조로아스터교","text":"서아시아를 처음으로 통일한 나라는 아시리아였어요. 그런데 아시리아는 정복한 민족을 가혹하게 다스려 반란이 잇따랐고 곧 무너졌어요. 그 뒤 기원전 6세기에 일어난 페르시아(아케메네스 왕조)는 서아시아와 이집트를 아우르는 큰 제국을 세웠어요. 특히 다리우스 1세 때 넓은 영토를 다스리는 방","keywords":["왕의 길","조로아스터교"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#c1","kind":"concept","title":"그리스의 폴리스","text":"그리스는 산이 많고 평야가 좁아서 하나의 큰 나라 대신 여러 개의 작은 도시 국가가 생겼어요. 이것을 폴리스라고 해요. 기원전 8세기 무렵부터 여러 폴리스가 생겨났어요. 폴리스의 중심에는 신전을 세운 언덕인 아크로폴리스와, 시민들이 모여 이야기하고 물건을 사고팔던 광장인 아고라가 있었어","keywords":["폴리스"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#c2","kind":"concept","title":"아테네 민주 정치의 모습과 한계","text":"아테네에서는 시민이 나라의 일을 직접 결정하는 민주 정치가 발달했어요. 클레이스테네스는 독재자가 될 위험이 있는 사람의 이름을 도자기 조각에 써서 투표하고, 많이 나온 사람을 나라 밖으로 내보내는 도편 추방제를 만들었어요. 페르시아 전쟁(기원전 5세기 초)에서 아테네가 앞장서 페르시아를","keywords":["도편 추방제","직접 민주 정치"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#c3","kind":"concept","title":"알렉산드로스 제국과 헬레니즘 문화","text":"폴리스들이 약해진 틈에 그리스 북쪽의 마케도니아가 그리스를 정복했어요. 마케도니아의 알렉산드로스는 기원전 334년부터 동방 원정에 나서 페르시아를 무너뜨리고, 이집트에서 인도 서북부에 이르는 큰 제국을 세웠어요. 알렉산드로스는 정복한 곳에 알렉산드리아라는 이름의 도시를 여럿 세우고 그리","keywords":["폴리스","헬레니즘 문화"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#c4","kind":"concept","title":"로마 — 공화정에서 제정으로","text":"이탈리아반도의 작은 도시에서 시작한 로마는 기원전 509년 왕을 몰아내고 공화정을 시작했어요. 공화정은 왕 없이 시민이 뽑은 대표들이 나라를 다스리는 정치예요. 집정관 2명(임기 1년)이 나라를 이끌고, 귀족으로 이루어진 원로원이 큰 힘을 가졌어요. 평민들의 요구로 평민을 보호하는 호민","keywords":["공화정","제정"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#c5","kind":"concept","title":"로마의 법과 건축, 크리스트교","text":"로마 사람들은 넓은 제국을 다스리는 데 쓸모 있는 실용적인 문화를 발달시켰어요. 법: 12표법에서 시작해, 로마 시민이 아닌 사람에게도 적용되는 만민법으로 발전했어요. 뒤에 동로마 제국의 유스티니아누스 황제가 로마법을 정리한 법전을 펴냈고, 이는 근대 유럽 여러 나라의 법에 영향을 주었","keywords":["만민법"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t0","kind":"term","title":"왕의 길","text":"페르시아가 수도 수사에서 소아시아의 사르디스까지 닦은 큰 도로예요. 곳곳에 역을 두어 명령과 소식을 빠르게 전했어요.","keywords":["왕의 길"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t1","kind":"term","title":"조로아스터교","text":"페르시아에서 널리 믿은 종교예요. 선한 신과 악한 신의 싸움, 최후의 심판을 가르치고 불을 신성하게 여겼어요.","keywords":["조로아스터교"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t2","kind":"term","title":"폴리스","text":"고대 그리스의 작은 도시 국가예요. 아크로폴리스(신전 언덕)와 아고라(광장)가 중심이었어요.","keywords":["폴리스"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t3","kind":"term","title":"도편 추방제","text":"독재자가 될 위험이 있는 사람의 이름을 도자기 조각에 써서 투표하고, 많이 나온 사람을 나라 밖으로 내보낸 아테네의 제도예요.","keywords":["도편 추방제"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t4","kind":"term","title":"직접 민주 정치","text":"시민이 대표를 거치지 않고 직접 모여 나라의 일을 결정하는 정치예요. 아테네의 민회가 그 예예요.","keywords":["직접 민주 정치"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t5","kind":"term","title":"헬레니즘 문화","text":"알렉산드로스의 동방 원정 뒤 그리스 문화와 오리엔트 문화가 어우러져 생긴 문화예요. 세계 시민주의가 특징이에요.","keywords":["헬레니즘 문화"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t6","kind":"term","title":"공화정","text":"왕 없이 시민이 뽑은 대표들이 나라를 다스리는 정치예요. 로마는 집정관·원로원·민회를 두었어요.","keywords":["공화정"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t7","kind":"term","title":"제정","text":"황제가 나라를 다스리는 정치예요. 로마에서는 기원전 27년 아우구스투스 때 시작되었어요.","keywords":["제정"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t8","kind":"term","title":"만민법","text":"로마 시민이 아닌 사람에게도 두루 적용된 로마의 법이에요.","keywords":["만민법"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#t9","kind":"term","title":"밀라노 칙령","text":"313년 콘스탄티누스 황제가 크리스트교를 공인한 명령이에요.","keywords":["밀라노 칙령"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#f0","kind":"faq","title":"아테네가 민주 정치를 했는데 왜 한계가 있다고 해요?","text":"아테네에서 정치에 참여할 수 있는 사람은 성인 남성 시민뿐이었어요. 인구의 많은 부분을 차지한 여성·노예·외국인은 참여할 수 없었지요. 오늘날 민주주의는 일정한 나이가 된 모든 국민이 참여하는 것을 원칙으로 하니, 그와 비교하면 참여 범위가 좁았어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#f1","kind":"faq","title":"공화정과 제정은 뭐가 달라요?","text":"공화정은 왕 없이 시민이 뽑은 대표(로마의 집정관)와 원로원이 함께 나라를 다스리는 정치예요. 제정은 황제 한 사람에게 권력이 모인 정치예요. 로마는 기원전 509년부터 공화정이었다가, 기원전 27년 아우구스투스 때부터 제정이 되었어요.","keywords":["공화정","제정"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#f2","kind":"faq","title":"크리스트교 공인과 국교는 뭐가 달라요?","text":"공인은 \"믿어도 된다\"고 나라가 인정한 것이에요(313년 밀라노 칙령). 국교는 \"나라의 공식 종교\"로 정한 것이에요(392년 테오도시우스 황제). 박해 → 공인 → 국교 순서로 크리스트교의 지위가 높아졌어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#m0","kind":"mistake","title":"자주 하는 실수","text":"공화정 시작과 제정 시작을 헷갈리는 실수 — 왕을 몰아낸 것(기원전 509년)은 공화정의 시작, 아우구스투스 칭호(기원전 27년)는 제정의 시작이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#m1","kind":"mistake","title":"자주 하는 실수","text":"크리스트교 공인(313년, 콘스탄티누스)과 국교화(392년, 테오도시우스)를 섞는 실수 — 공인이 먼저예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-03#m2","kind":"mistake","title":"자주 하는 실수","text":"아테네 민주 정치에 모든 주민이 참여했다고 생각하는 실수 — 성인 남성 시민만 참여했어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-03","grade":"m2"},
{"id":"hist-m-1-04","kind":"unit","title":"중국과 인도, 동아시아 문화권","text":"춘추 전국 시대부터 수·당까지 중국의 변화와 인도의 불교를 살펴보고, 동아시아 문화권이 생긴 과정을 알아봐요. 춘추 전국 시대의 변화와 제자백가의 주장을 비교할 수 있어요. 진·한과 수·당이 중국을 통일하고 다스린 방법을 설명할 수 있어요. 마우리아·쿠샨 왕조 때 불교가 퍼진 과정과 간다라 미술, 비단길을 통한 교류를 설명할 수 있어요. 동아시아 문화권의…","keywords":["제자백가","군현제","유학의 관학화","대승 불교","간다라 미술","비단길","과거제","율령","동아시아 문화권"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#c0","kind":"concept","title":"춘추 전국 시대와 제자백가","text":"상(은)을 무너뜨린 주는 왕족과 공신에게 땅을 나누어 주고 제후로 삼아 다스리게 했어요(봉건제). 그런데 기원전 770년 주가 도읍을 동쪽으로 옮긴 뒤 왕실의 힘이 약해지자, 제후들이 서로 다투는 춘추 전국 시대(기원전 770년~기원전 221년)가 이어졌어요. 이 시기의 변화 철제 농기","keywords":["제자백가"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#c1","kind":"concept","title":"진·한의 통일과 황제 중심의 통치","text":"진은 법가 사상을 받아들여 나라를 강하게 만들고, 기원전 221년 중국을 처음으로 통일했어요. 진의 왕은 스스로 황제라 부르며 시황제가 되었어요. 진 시황제의 정책 군현제: 전국을 군과 현으로 나누고 중앙에서 관리를 보내 다스렸어요. 황제에게 권력이 모였지요. 지역마다 달랐던 화폐·도량","keywords":["군현제"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#c2","kind":"concept","title":"마우리아·쿠샨 왕조와 불교","text":"인도에서는 일찍이 카스트제라는 엄격한 신분 제도가 자리 잡았고, 제사를 맡은 브라만이 가장 높은 신분이었어요. 기원전 6세기 무렵 고타마 싯다르타(석가모니)가 불교를 열었어요. 불교는 신분에 따른 차별에 반대하고, 누구나 깨달음을 얻으면 고통에서 벗어날 수 있다(해탈)고 가르쳤어요. 마","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#c3","kind":"concept","title":"비단길을 통한 동서 교류","text":"한 무제는 흉노를 함께 칠 나라를 찾으려고 장건을 서역(중앙아시아)에 보냈어요(기원전 2세기 후반). 동맹은 이루지 못했지만, 장건 덕분에 서역의 사정이 알려지면서 중국과 서쪽 세계를 잇는 교역로가 활발해졌어요. 이 길을 따라 중국의 비단이 서쪽으로 많이 팔려 나가서 비단길(실크로드)이","keywords":["비단길"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#c4","kind":"concept","title":"위진 남북조와 수·당 — 율령 체제와 국제 문화","text":"220년 한이 무너진 뒤 약 400년 가까이 중국은 여러 나라로 나뉘었어요. 이 시기를 위진 남북조 시대라고 해요. 위·촉·오의 삼국이 다투다 진(晉)이 잠시 통일했지만, 곧 북방 유목 민족이 화북 지방으로 내려왔어요. 많은 한족이 남쪽(강남)으로 옮겨 가면서 강남이 개발되었어요. 북쪽","keywords":["과거제","율령"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#c5","kind":"concept","title":"동아시아 문화권의 형성","text":"중국과 교류하며 만주·한반도와 일본에서도 고대 국가가 성장했어요. 만주·한반도: 고구려·백제·신라는 4~6세기에 걸쳐 율령을 반포하고 불교를 받아들여 나라의 기틀을 다졌어요. 유학을 가르치는 교육 기관도 두었어요. 일본: 야마토 정권이 성장했고, 한반도의 여러 나라를 통해 한자·유교·불","keywords":["율령","동아시아 문화권"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t0","kind":"term","title":"제자백가","text":"춘추 전국 시대에 나라를 다스리는 방법을 내놓은 여러 사상가와 학파예요. 유가·도가·법가·묵가 등이 있어요.","keywords":["제자백가"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t1","kind":"term","title":"군현제","text":"전국을 군과 현으로 나누고 중앙에서 관리를 보내 다스리는 제도예요. 진 시황제가 전국에 실시했어요.","keywords":["군현제"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t2","kind":"term","title":"유학의 관학화","text":"한 무제 때 유학을 나라를 다스리는 기본 사상으로 삼고, 유학을 공부한 사람을 관리로 뽑은 일이에요.","keywords":["유학의 관학화"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t3","kind":"term","title":"대승 불교","text":"자기만이 아니라 많은 사람(중생)을 구제하는 것을 중시하는 불교예요. 쿠샨 왕조 때 발전해 동아시아로 전해졌어요.","keywords":["대승 불교"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t4","kind":"term","title":"간다라 미술","text":"쿠샨 왕조 때 헬레니즘 문화의 영향을 받아 그리스 조각처럼 사실적인 불상을 만든 미술이에요.","keywords":["간다라 미술"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t5","kind":"term","title":"비단길","text":"중국과 서아시아·지중해를 이은 교역로예요. 중국의 비단이 서쪽으로 많이 팔려 나가서 붙은 이름이에요.","keywords":["비단길"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t6","kind":"term","title":"과거제","text":"시험을 치러 관리를 뽑는 제도예요. 수에서 처음 실시하고 당이 이어받았어요.","keywords":["과거제"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t7","kind":"term","title":"율령","text":"율은 형벌에 관한 법, 령은 나라를 다스리는 제도에 관한 법이에요. 당이 율령 체제를 갖추었어요.","keywords":["율령"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#t8","kind":"term","title":"동아시아 문화권","text":"한자·유교·불교·율령을 함께 나누며 형성된 중국·한국·일본 등의 문화권이에요.","keywords":["동아시아 문화권"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#f0","kind":"faq","title":"유가, 도가, 법가는 어떻게 구별해요?","text":"핵심 낱말로 구별해요. 유가는 인과 예(공자, 맹자), 도가는 무위자연(노자, 장자), 법가는 법과 상벌(한비자)이에요. \"덕으로 다스리자\" → 유가, \"자연스럽게 두자\" → 도가, \"법으로 다스리자\" → 법가라고 기억해 보세요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#f1","kind":"faq","title":"상좌부 불교와 대승 불교는 뭐가 달라요?","text":"상좌부 불교는 수행을 통한 개인의 해탈을 중시하고, 마우리아 왕조 때 스리랑카·동남아시아로 퍼졌어요. 대승 불교는 많은 사람(중생)의 구제를 중시하고, 쿠샨 왕조 때 발전해 중국·한국·일본으로 전해졌어요.","keywords":["대승 불교"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#f2","kind":"faq","title":"율령이 뭐예요?","text":"율은 죄와 벌을 정한 법(형법), 령은 나라를 다스리는 제도와 조직을 정한 법(행정법)이에요. 당은 율령으로 관청 조직(3성 6부), 토지 제도(균전제), 세금(조용조), 군대(부병제)를 정해 나라를 체계적으로 다스렸고, 이 방식이 동아시아 여러 나라로 퍼졌어요.","keywords":["율령"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#m0","kind":"mistake","title":"자주 하는 실수","text":"진 시황제와 한 무제를 헷갈리는 실수 — 법가·군현제·분서갱유·만리장성은 진 시황제, 유학의 관학화·장건 파견은 한 무제예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#m1","kind":"mistake","title":"자주 하는 실수","text":"상좌부 불교와 대승 불교의 전파 방향을 바꾸어 쓰는 실수 — 상좌부는 스리랑카·동남아시아(마우리아), 대승은 중국·한국·일본(쿠샨)이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-04#m2","kind":"mistake","title":"자주 하는 실수","text":"과거제를 한이나 당에서 시작했다고 아는 실수 — 과거제는 수에서 처음 실시했고 당이 이어받았어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-04","grade":"m2"},
{"id":"hist-m-1-05","kind":"unit","title":"세계 종교와 지역 문화","text":"굽타 왕조의 힌두교, 비잔티움 제국과 이슬람 세계, 서유럽 크리스트교 세계가 발전하고 서로 만난 모습을 알아봐요. 굽타 왕조 때 힌두교와 인도 고전 문화가 자리 잡은 모습을 설명할 수 있어요. 비잔티움 제국과 이슬람 세계가 발전한 과정과 그 문화의 특징을 말할 수 있어요. 서유럽 봉건 사회의 구조와 교황권의 성장을 설명할 수 있어요. 십자군 전쟁의 원인과…","keywords":["힌두교","카스트제","비잔티움 제국","그리스 정교","칼리프","쿠란","아라베스크","봉건 제도","장원","십자군 전쟁"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#c0","kind":"concept","title":"사산 왕조 페르시아와 굽타 왕조","text":"3세기 초 이란 지역에서 사산 왕조 페르시아가 일어났어요. 사산 왕조는 조로아스터교를 나라의 종교(국교)로 삼고, 동서를 잇는 교역로의 한가운데에서 중계 무역으로 번영했어요. 화려한 유리 그릇·은 그릇 같은 사산 왕조의 공예 문화는 비단길을 따라 동아시아까지 전해졌어요. 7세기 중엽 이","keywords":["힌두교","카스트제"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#c1","kind":"concept","title":"서로마 제국의 멸망과 비잔티움 제국","text":"로마 제국은 4세기 말 동서로 나뉘었어요. 그중 서로마 제국은 게르만족의 이동으로 흔들리다가 476년 게르만 용병 대장 오도아케르에게 멸망했어요. 동로마 제국은 그 뒤에도 약 1,000년 동안 이어졌어요. 수도 콘스탄티노폴리스의 옛 이름(비잔티움)을 따서 비잔티움 제국이라고 불러요. 유","keywords":["비잔티움 제국","그리스 정교"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#c2","kind":"concept","title":"이슬람교의 성립과 이슬람 세계의 확장","text":"7세기 초 아라비아반도의 상업 도시 메카에서 무함마드가 유일신 알라를 믿고 따르라는 가르침을 전하며 이슬람교를 창시했어요. 이슬람교는 신 앞에서 모든 사람이 평등하다고 가르쳤어요. 메카의 귀족들이 박해하자 무함마드는 622년 메디나로 옮겨 갔어요. 이 일을 헤지라(이주)라고 하며, 이해","keywords":["칼리프","쿠란"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#c3","kind":"concept","title":"이슬람 문화의 발달과 전파","text":"이슬람 세계는 넓은 땅에 여러 민족이 어울려 살았기 때문에, 이슬람교와 아랍어를 바탕으로 그리스·페르시아·인도 문화를 받아들여 새로운 문화를 만들었어요. 언어와 종교: 쿠란은 아랍어로만 읽도록 해서 아랍어가 공통어가 되었어요. 쿠란을 바탕으로 신학과 법학이 발달했어요. 건축과 미술: 둥","keywords":["쿠란","아라베스크"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#c4","kind":"concept","title":"프랑크 왕국과 서유럽의 봉건 사회","text":"서로마 제국이 무너진 뒤 서유럽에는 게르만족의 여러 나라가 세워졌어요. 그중 프랑크 왕국이 가장 크게 성장했어요. 클로비스는 로마 가톨릭으로 개종해 로마 교회의 지지를 얻었고, 카롤루스 대제는 서유럽 대부분을 통합해 800년 교황에게서 서로마 황제의 관을 받았어요. 카롤루스 대제가 죽은","keywords":["봉건 제도","장원"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#c5","kind":"concept","title":"십자군 전쟁과 그 영향","text":"11세기 셀주크 튀르크가 크리스트교의 성지 예루살렘을 차지하고 비잔티움 제국을 위협했어요. 비잔티움 황제가 도움을 청하자 교황 우르바누스 2세는 1095년 클레르몽 공의회에서 성지를 되찾자고 호소했어요. 이렇게 시작된 십자군 전쟁은 1096년부터 약 200년 동안 여러 차례 이어졌어요.","keywords":["비잔티움 제국","십자군 전쟁"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t0","kind":"term","title":"힌두교","text":"굽타 왕조 때 브라만교에 민간 신앙과 불교 요소가 더해져 자리 잡은 인도의 종교예요. 비슈누·시바 등 여러 신을 섬겨요.","keywords":["힌두교"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t1","kind":"term","title":"카스트제","text":"태어날 때 정해진 신분에 따라 직업과 결혼, 생활이 정해지는 인도의 신분 제도예요. 굽타 왕조 때 『마누 법전』과 함께 굳게 자리 잡았어요.","keywords":["카스트제"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t2","kind":"term","title":"비잔티움 제국","text":"서로마 제국이 무너진 뒤에도 1453년까지 이어진 동로마 제국이에요. 수도는 콘스탄티노폴리스예요.","keywords":["비잔티움 제국"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t3","kind":"term","title":"그리스 정교","text":"1054년 크리스트교가 나뉠 때 비잔티움 제국을 중심으로 이어진 교회예요. 러시아 등 슬라브족에게 전해졌어요.","keywords":["그리스 정교"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t4","kind":"term","title":"칼리프","text":"무함마드의 후계자로서 이슬람 공동체의 종교와 정치를 함께 이끈 지도자예요.","keywords":["칼리프"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t5","kind":"term","title":"쿠란","text":"이슬람교의 경전이에요. 무함마드가 받은 알라의 계시를 아랍어로 모은 책이에요.","keywords":["쿠란"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t6","kind":"term","title":"아라베스크","text":"식물 덩굴·도형·글자를 엮어 만든 이슬람의 장식 무늬예요. 우상 숭배를 금지해서 사람·동물 대신 이런 무늬가 발달했어요.","keywords":["아라베스크"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t7","kind":"term","title":"봉건 제도","text":"주군이 봉신에게 땅(봉토)을 주고, 봉신은 충성과 군사적 봉사로 보답하는 서유럽 중세의 계약 관계예요.","keywords":["봉건 제도"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t8","kind":"term","title":"장원","text":"영주가 다스리던 중세 서유럽의 농촌 단위예요. 농노가 영주의 땅을 경작하고 세금을 냈어요.","keywords":["장원"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#t9","kind":"term","title":"십자군 전쟁","text":"11세기 말부터 약 200년 동안 서유럽 크리스트교 세계가 성지 예루살렘을 되찾겠다며 일으킨 원정이에요.","keywords":["십자군 전쟁"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#f0","kind":"faq","title":"힌두교랑 불교는 같은 종교예요?","text":"아니에요. 둘 다 인도에서 생겼지만 다른 종교예요. 불교는 카스트제를 비판하며 누구나 깨달음을 얻을 수 있다고 가르쳤어요. 힌두교는 옛 브라만교에 민간 신앙과 불교 요소가 더해진 종교로, 카스트에 따른 의무를 중요하게 여겼어요. 굽타 왕조 이후 인도에서는 힌두교가 널리 퍼졌어요.","keywords":["힌두교"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#f1","kind":"faq","title":"칼리프랑 교황은 뭐가 달라요?","text":"칼리프는 무함마드의 후계자로서 이슬람 공동체의 종교와 정치를 함께 이끈 지도자예요. 교황은 로마 가톨릭 교회의 최고 성직자로, 서유럽에서는 왕·황제와 따로 있으면서 때로 권한을 두고 다투었어요.","keywords":["칼리프"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#f2","kind":"faq","title":"농노는 노예랑 똑같은 거예요?","text":"비슷해 보이지만 달라요. 농노는 집과 가족, 약간의 재산을 가질 수 있었고 물건처럼 사고팔리지 않았어요. 하지만 영주의 땅을 경작해 주고 여러 세금을 내야 했으며, 영주의 허락 없이 장원을 떠날 수 없었어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#m0","kind":"mistake","title":"자주 하는 실수","text":"\"아라비아 숫자는 아라비아에서 만들어졌다\"고 생각하는 실수 — 처음 만든 곳은 인도이고, 이슬람 세계가 유럽에 전해 주었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#m1","kind":"mistake","title":"자주 하는 실수","text":"우마이야 왕조와 아바스 왕조를 헷갈리는 실수 — 우마이야는 다마스쿠스·아랍인 우대, 아바스는 바그다드·차별 없음이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-05#m2","kind":"mistake","title":"자주 하는 실수","text":"십자군 전쟁 뒤 교황권이 강해졌다고 생각하는 실수 — 교황이 앞장선 전쟁이 실패해서 교황권은 약해지고 왕권이 강해졌어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-05","grade":"m2"},
{"id":"hist-m-1-06","kind":"unit","title":"몽골 제국과 아시아의 변화","text":"송과 몽골 제국 때 넓어진 교역과 문화 교류, 명·청과 에도 막부, 무굴 제국의 정치와 사회 변화를 비교해요. 송의 문치주의와 경제·문화의 발전을 설명할 수 있어요. 몽골 제국이 유라시아를 연결하며 교역과 문화 교류를 넓힌 모습을 말할 수 있어요. 명·청과 에도 막부의 통치와 대외 정책을 비교할 수 있어요. 무굴 제국의 통치와 인도·이슬람 문화의 특징을 …","keywords":["문치주의","사대부","성리학","역참","색목인","조공·책봉","해금","산킨코타이","조닌","인도·이슬람 문화"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#c0","kind":"concept","title":"송의 문치주의와 북방 민족의 성장","text":"당이 멸망한 뒤 혼란을 거쳐 960년 조광윤(태조)이 송을 세웠어요. 그전까지 군대를 가진 지방 세력(절도사)이 황제를 위협하던 것을 막으려고, 송은 무관보다 글을 아는 문관을 우대하는 문치주의를 폈어요. 과거제를 고쳐 황제가 직접 마지막 시험을 보고 관리를 뽑았어요. 과거를 통해 관리","keywords":["문치주의","사대부"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#c1","kind":"concept","title":"송의 경제와 문화","text":"송 때는 강남(양쯔강 남쪽) 지방이 크게 개발되어 벼농사가 발달했어요. 먹을 것이 넉넉해지자 인구가 늘고 상업과 수공업이 활발해졌어요. 상업 도시: 수도 카이펑과 항저우 같은 큰 도시가 번성했고, 상인과 수공업자는 동업 조합을 만들었어요. 지폐: 거래가 늘어 무거운 동전만으로는 불편해지","keywords":["사대부","성리학"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#c2","kind":"concept","title":"몽골 제국과 유라시아 교역","text":"1206년 칭기즈 칸이 몽골 부족을 통일했어요. 몽골은 뛰어난 기마 군대로 금과 서하를 공격하고 중앙아시아·서아시아·러시아까지 진출해, 아시아와 유럽에 걸친 역사상 가장 넓은 제국을 이루었어요. 쿠빌라이 칸은 1271년 나라 이름을 원으로 정하고 대도(지금의 베이징)를 수도로 삼았으며,","keywords":["역참","색목인"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#c3","kind":"concept","title":"명·청의 통치와 대외 정책","text":"원의 지배에 맞선 반란 속에서 주원장(홍무제)이 1368년 명을 세우고 몽골을 북쪽으로 몰아냈어요. 명은 한족의 전통을 되살리고 유교를 통치 이념으로 삼았으며, 황제의 권한을 크게 강화했어요. 영락제는 수도를 베이징으로 옮겼어요. 명의 대외 정책 조공·책봉: 주변 나라가 사신을 보내 예","keywords":["조공·책봉","해금"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#c4","kind":"concept","title":"에도 막부와 조닌 문화","text":"일본에서는 오랜 전국 시대의 혼란을 거쳐 도쿠가와 이에야스가 1603년 에도(지금의 도쿄)에 에도 막부를 열었어요. 막부의 우두머리인 쇼군이 전국을 다스리고, 지방은 다이묘(영주)가 각자의 영지(번)를 다스렸어요. 이를 막번 체제라고 해요. 막부는 다이묘가 힘을 키우지 못하게 산킨코타이","keywords":["산킨코타이","조닌"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#c5","kind":"concept","title":"무굴 제국과 인도·이슬람 문화","text":"1526년 중앙아시아에서 온 바부르가 북인도에 이슬람 왕조인 무굴 제국을 세웠어요. 제3대 황제 악바르는 북인도의 대부분을 통일하고 제국의 기틀을 다졌어요. 인도 사람 대부분은 힌두교도였기 때문에 악바르는 관용 정책을 폈어요. 이슬람교도가 아닌 사람에게 걷던 인두세(지즈야)를 없앴어요.","keywords":["인도·이슬람 문화"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t0","kind":"term","title":"문치주의","text":"무관보다 학자 출신 문관을 우대해 나라를 다스리는 정치예요. 송이 펼쳤어요.","keywords":["문치주의"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t1","kind":"term","title":"사대부","text":"송 때 과거를 통해 관리가 된 학자 출신 지배층이에요. 성리학을 발전시켰어요.","keywords":["사대부"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t2","kind":"term","title":"성리학","text":"송 때 유학을 새롭게 해석한 학문이에요. 남송의 주희가 집대성해 주자학이라고도 해요.","keywords":["성리학"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t3","kind":"term","title":"역참","text":"몽골 제국이 큰 길을 따라 일정한 거리마다 말과 숙소, 음식을 마련해 둔 교통·통신 제도예요.","keywords":["역참"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t4","kind":"term","title":"색목인","text":"원에서 서역·이슬람 지역 출신 사람들을 부르던 말이에요. 몽골인 다음으로 대우받았어요.","keywords":["색목인"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t5","kind":"term","title":"조공·책봉","text":"주변 나라가 사신과 예물을 보내면(조공) 중국 황제가 그 나라 왕을 인정해 주는(책봉) 외교 관계예요.","keywords":["조공·책봉"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t6","kind":"term","title":"해금","text":"명이 민간인이 마음대로 바다로 나가 무역하는 것을 금지한 정책이에요.","keywords":["해금"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t7","kind":"term","title":"산킨코타이","text":"에도 막부가 다이묘에게 정해진 기간마다 에도와 영지를 오가며 머물게 한 제도예요. 참근 교대제라고도 해요.","keywords":["산킨코타이"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t8","kind":"term","title":"조닌","text":"에도 시대 도시에 사는 상인과 수공업자예요. 가부키·우키요에 같은 조닌 문화를 즐겼어요.","keywords":["조닌"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#t9","kind":"term","title":"인도·이슬람 문화","text":"무굴 제국 때 힌두 문화와 이슬람 문화가 어우러져 생긴 문화예요. 타지마할, 우르두어, 시크교가 대표적이에요.","keywords":["인도·이슬람 문화"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#f0","kind":"faq","title":"송은 돈도 많고 문화도 발달했는데 왜 북방 민족한테 졌어요?","text":"송은 장군들이 반란을 일으키지 못하게 학자 출신 관리를 우대하는 문치주의를 폈어요. 그 덕에 나라 안은 안정되었지만 군사력이 약해졌어요. 그래서 거란·여진에게 비단과 은을 보내 평화를 사야 했고, 결국 금에게 화북 지방을 잃었어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#f1","kind":"faq","title":"원이랑 몽골 제국은 같은 거예요?","text":"완전히 같지는 않아요. 몽골 제국은 칭기즈 칸 이후 유라시아에 걸쳐 세워진 큰 제국 전체를 말하고, 원은 그중 쿠빌라이 칸이 중국 지역을 중심으로 다스린 나라예요. 서아시아와 러시아 쪽에는 다른 몽골 국가들이 있었어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#f2","kind":"faq","title":"조공은 그냥 선물을 바치는 거예요?","text":"조공은 주변 나라가 사신과 예물을 보내고, 중국 황제가 그 나라 왕을 인정하며(책봉) 답례품을 주는 외교 관계예요. 예의를 갖춘 외교이면서 무역의 기회이기도 했어요. 명은 해금 정책을 펴서 이런 조공을 통해서만 무역하게 했어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#m0","kind":"mistake","title":"자주 하는 실수","text":"칭기즈 칸과 쿠빌라이 칸을 헷갈리는 실수 — 칭기즈 칸은 1206년 몽골을 통일했고, 쿠빌라이 칸은 1271년 나라 이름을 원으로 정하고 남송을 무너뜨렸어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#m1","kind":"mistake","title":"자주 하는 실수","text":"해금과 쇄국 정책을 모두 \"교류를 완전히 끊은 것\"으로 생각하는 실수 — 명은 조공 무역을, 에도 막부는 네덜란드와의 데지마 교역을 허락했어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-06#m2","kind":"mistake","title":"자주 하는 실수","text":"타지마할을 힌두교 사원으로 생각하는 실수 — 무굴 제국의 샤자한이 왕비를 위해 세운 무덤으로, 인도·이슬람 문화의 대표 건축이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-06","grade":"m2"},
{"id":"hist-m-1-07","kind":"unit","title":"오스만 제국과 근대 유럽","text":"오스만 제국의 성장과 유럽의 르네상스·종교 개혁·신항로 개척이 세계를 어떻게 바꾸었는지 알아봐요. 오스만 제국이 여러 민족과 종교를 아우르며 성장한 모습을 설명할 수 있어요. 르네상스와 종교 개혁이 유럽 사회에 가져온 변화를 말할 수 있어요. 신항로 개척이 아메리카·아프리카와 유럽, 아시아에 가져온 변화를 설명할 수 있어요. 영국과 프랑스가 재정·군사 국…","keywords":["술탄","예니체리","밀레트","르네상스","인문주의","면벌부","종교 개혁","대서양 노예 무역","가격 혁명","절대 왕정"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#c0","kind":"concept","title":"오스만 제국의 성장과 통치","text":"13세기 말 소아시아(지금의 튀르키예 지역)에서 튀르크족이 오스만 제국을 세웠어요. 1453년 메흐메트 2세가 콘스탄티노폴리스를 점령해 비잔티움 제국을 무너뜨렸고, 이 도시를 이스탄불로 이름을 바꾸어 수도로 삼았어요. 16세기 술레이만 1세 때 오스만 제국은 전성기를 맞았어요. 헝가리를","keywords":["술탄","예니체리","밀레트"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#c1","kind":"concept","title":"르네상스와 인문주의","text":"르네상스는 \"다시 태어남(부활)\"이라는 뜻이에요. 14세기 무렵 이탈리아에서 고대 그리스·로마 문화를 되살려 인간을 중심에 두고 현실의 삶을 소중히 여기려는 움직임이 시작되었어요. 이런 생각을 인문주의라고 해요. 왜 이탈리아에서 시작되었을까요? 지중해 무역으로 피렌체·베네치아 같은 도시","keywords":["르네상스","인문주의"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#c2","kind":"concept","title":"종교 개혁과 신교·구교의 대립","text":"16세기 초 로마 가톨릭 교회는 성당을 짓는 데 필요한 돈을 모으려고, 죄에 대한 벌을 면해 준다는 면벌부를 팔았어요. 1517년 독일의 루터는 \"사람은 면벌부가 아니라 믿음으로 구원받으며, 신앙의 기준은 성경\"이라며 95개조 반박문을 발표했어요. 루터는 성경을 독일어로 옮겨 누구나 읽","keywords":["면벌부","종교 개혁"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#c3","kind":"concept","title":"신항로 개척과 아메리카·아프리카의 비극","text":"15세기 유럽 사람들은 아시아의 향신료(후추 등)와 비단을 원했어요. 그런데 동방으로 가는 길은 오스만 제국이 차지하고 있었고, 지중해 무역은 이탈리아 상인들이 쥐고 있었어요. 그래서 대서양에 닿아 있던 포르투갈과 에스파냐는 왕실의 지원 아래 바다로 직접 아시아에 가는 새 길을 찾아 나","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#c4","kind":"concept","title":"세계 교역망의 확대가 가져온 변화","text":"신항로 개척으로 유럽·아메리카·아프리카·아시아가 바닷길로 이어지면서 세계 여러 지역이 하나의 교역망으로 묶이기 시작했어요. 유럽의 변화 무역의 중심이 지중해에서 대서양 연안으로 옮겨 갔어요. 리스본, 안트베르펜, 암스테르담, 런던 같은 도시가 성장했어요. 거래하는 물건의 종류와 양이 크","keywords":["가격 혁명"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#c5","kind":"concept","title":"재정·군사 국가의 등장 — 영국과 프랑스","text":"16~18세기 유럽 나라들은 서로 자주 전쟁을 벌였어요. 전쟁에 이기려면 늘 대기하는 군대(상비군)와 나라 일을 맡는 관료가 필요했고, 이를 유지하려면 많은 돈이 들었어요. 그래서 세금을 거두고 돈을 빌리는 힘, 곧 재정을 키워 군사력을 뒷받침하는 나라들이 생겼어요. 이런 나라를 재정·","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t0","kind":"term","title":"술탄","text":"오스만 제국 등 이슬람 세계의 최고 통치자를 부르는 칭호예요.","keywords":["술탄"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t1","kind":"term","title":"예니체리","text":"크리스트교도 소년을 뽑아 이슬람교도로 교육·훈련한 오스만 제국 술탄 직속의 상비군이에요.","keywords":["예니체리"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t2","kind":"term","title":"밀레트","text":"오스만 제국에서 세금을 내는 대신 자기 신앙과 관습에 따라 스스로 일을 처리하게 한 종교 공동체예요.","keywords":["밀레트"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t3","kind":"term","title":"르네상스","text":"\"다시 태어남\"이라는 뜻으로, 14세기 무렵 이탈리아에서 시작된 고대 그리스·로마 문화의 부흥 운동이에요.","keywords":["르네상스"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t4","kind":"term","title":"인문주의","text":"신보다 인간을 중심에 두고 인간의 가치와 현실의 삶을 소중히 여기는 생각이에요.","keywords":["인문주의"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t5","kind":"term","title":"면벌부","text":"로마 가톨릭 교회가 죄에 대한 벌을 면해 준다며 판 증서예요. 루터가 이를 비판했어요.","keywords":["면벌부"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t6","kind":"term","title":"종교 개혁","text":"16세기 루터, 칼뱅 등이 로마 가톨릭 교회의 잘못을 비판하며 일으킨 교회 개혁 운동이에요. 신교가 생겨났어요.","keywords":["종교 개혁"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t7","kind":"term","title":"대서양 노예 무역","text":"유럽 사람들이 아프리카 사람들을 강제로 끌고 가 아메리카에 노예로 판 무역이에요.","keywords":["대서양 노예 무역"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t8","kind":"term","title":"가격 혁명","text":"아메리카의 은이 대량으로 들어와 16세기 유럽의 물가가 크게 오른 일이에요.","keywords":["가격 혁명"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#t9","kind":"term","title":"절대 왕정","text":"왕이 관료제와 상비군을 바탕으로 강한 권력을 가지고 나라를 다스린 체제예요. 프랑스의 루이 14세가 대표적이에요.","keywords":["절대 왕정"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#f0","kind":"faq","title":"콜럼버스가 아메리카를 \"발견\"했다고 해도 돼요?","text":"유럽 사람의 입장에서는 몰랐던 땅을 처음 알게 된 것이지만, 아메리카에는 이미 오래전부터 원주민이 살며 아스테카·잉카 같은 문명을 이루고 있었어요. 그래서 요즘에는 \"콜럼버스가 아메리카에 도착했다\"처럼 원주민의 입장도 생각하는 표현을 함께 써요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#f1","kind":"faq","title":"신교랑 구교는 뭐가 달라요?","text":"구교는 로마 교황을 중심으로 한 로마 가톨릭이에요. 신교(프로테스탄트)는 종교 개혁으로 생긴 루터파, 칼뱅파, 영국 국교회 등을 말해요. 신교는 교황의 권위 대신 성경과 믿음을 신앙의 기준으로 삼았어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#f2","kind":"faq","title":"르네상스 때 왜 사람 그림이 갑자기 사실적으로 바뀌었어요?","text":"인문주의가 퍼지면서 사람 자체를 아름답고 소중한 존재로 보게 되었기 때문이에요. 화가들은 사람의 몸을 연구하고, 원근법으로 공간의 깊이를 나타내며 실제 눈으로 보는 것처럼 그리려 했어요.","keywords":["르네상스"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#m0","kind":"mistake","title":"자주 하는 실수","text":"콜럼버스와 바스쿠 다가마를 헷갈리는 실수 — 콜럼버스는 1492년 아메리카, 바스쿠 다가마는 1498년 희망봉을 돌아 인도에 닿았어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#m1","kind":"mistake","title":"자주 하는 실수","text":"르네상스를 \"옛것을 그대로 따라 한 것\"으로 생각하는 실수 — 고대 문화를 되살려 인간 중심의 새 문화를 만든 거예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-07#m2","kind":"mistake","title":"자주 하는 실수","text":"영국과 프랑스가 같은 방법으로 강해졌다고 생각하는 실수 — 프랑스는 왕권 강화, 영국은 왕과 의회의 협력이었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-07","grade":"m2"},
{"id":"hist-m-1-08","kind":"unit","title":"시민 혁명과 국민 국가","text":"미국 혁명과 프랑스 혁명이 인권과 민주주의의 길을 연 과정, 국민 국가가 생겨난 모습과 그 한계를 배워요. 영국 혁명과 계몽사상이 시민 혁명에 끼친 영향을 설명할 수 있어요. 미국 혁명과 프랑스 혁명의 전개 과정과 의의를 말할 수 있어요. 라틴 아메리카의 독립과 국민 국가의 형성 과정을 설명할 수 있어요. 시민 혁명의 한계와 참정권 확대 운동의 의미를 말…","keywords":["명예혁명","계몽사상","사회 계약설","삼권 분립","독립 선언","인권 선언","구제도","크리오요","국민 국가","참정권"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#c0","kind":"concept","title":"영국 혁명과 계몽사상","text":"17세기 영국 왕들은 의회를 무시하고 마음대로 세금을 걷으려 했어요. 의회는 1628년 권리 청원을 올려 의회의 동의 없이 세금을 걷지 말라고 요구했지만, 왕이 이를 어기자 왕을 따르는 쪽과 의회를 따르는 쪽 사이에 내전이 벌어졌어요. 크롬웰이 이끄는 의회파가 이겨 왕을 처형하고 공화정","keywords":["명예혁명","계몽사상"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#c1","kind":"concept","title":"미국 혁명 — 독립 선언과 연방 헌법","text":"북아메리카 동쪽 해안에는 영국의 13개 식민지가 있었어요. 식민지 사람들은 자기들이 뽑은 의회를 두고 어느 정도 스스로 다스렸어요. 그런데 영국은 프랑스와의 전쟁으로 돈이 모자라자 식민지에 새 세금을 매겼어요. 식민지 사람들은 영국 의회에 자기 대표가 없다며 \"대표 없이 과세 없다\"고 ","keywords":["독립 선언"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#c2","kind":"concept","title":"프랑스 혁명과 나폴레옹","text":"혁명 전 프랑스는 신분에 따라 권리가 달랐어요(구제도). 제1신분(성직자)과 제2신분(귀족)은 땅을 많이 가지고도 세금을 거의 내지 않았고, 인구 대부분인 제3신분(평민)이 세금을 떠맡았어요. 나라 살림이 어려워지자 루이 16세는 세금 문제를 논의하려고 1789년 삼부회를 열었어요. 제","keywords":["인권 선언","구제도"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#c3","kind":"concept","title":"아이티와 라틴 아메리카의 독립","text":"카리브해의 프랑스 식민지 생도맹그에서는 많은 흑인 노예가 설탕 농장에서 고되게 일했어요. 프랑스 혁명의 소식이 전해지자 노예들은 자유를 외치며 봉기했고, 투생 루베르튀르 등의 지도 아래 싸웠어요. 마침내 1804년 아이티가 독립했어요. 아이티는 라틴 아메리카에서 처음 독립한 나라이자, ","keywords":["크리오요"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#c4","kind":"concept","title":"자유주의·민족주의와 국민 국가의 형성","text":"나폴레옹이 몰락한 뒤 유럽의 지배층은 빈 회의를 열어 유럽을 혁명 이전처럼 되돌리려 했어요(빈 체제). 하지만 혁명이 퍼뜨린 두 가지 생각은 막을 수 없었어요. 자유주의: 개인의 자유와 권리를 보장하고, 헌법과 의회를 통해 다스려야 한다는 생각 민족주의: 같은 언어·역사·문화를 가진 사","keywords":["국민 국가"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#c5","kind":"concept","title":"시민 혁명의 의의와 한계, 참정권 확대","text":"시민 혁명은 왕과 귀족의 특권을 무너뜨리고 자유·평등, 국민 주권, 법에 따른 정치를 내세워 오늘날 민주주의의 바탕을 놓았어요. 하지만 처음부터 모든 사람이 권리를 누린 것은 아니에요. 재산 있는 남성 중심: 처음에는 일정한 재산을 가진 남성만 투표할 수 있는 경우가 많았어요. 여성: ","keywords":["독립 선언","참정권"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t0","kind":"term","title":"명예혁명","text":"1688년 영국 의회가 피를 흘리지 않고 왕을 바꾼 일이에요. 이듬해 권리 장전이 승인되어 입헌 군주제의 바탕이 되었어요.","keywords":["명예혁명"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t1","kind":"term","title":"계몽사상","text":"18세기에 사람의 이성으로 낡은 제도와 잘못된 생각을 비판하고 고치려 한 사상이에요.","keywords":["계몽사상"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t2","kind":"term","title":"사회 계약설","text":"국가는 사람들이 자기 권리를 지키기 위해 서로 약속해 만든 것이라는 생각이에요. 로크·루소가 대표적이에요.","keywords":["사회 계약설"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t3","kind":"term","title":"삼권 분립","text":"국가 권력을 입법·행정·사법으로 나누어 서로 견제하게 하는 원리예요. 몽테스키외가 주장했어요.","keywords":["삼권 분립"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t4","kind":"term","title":"독립 선언","text":"1776년 미국 13개 식민지 대표들이 영국에서 독립한다고 밝힌 선언이에요. 천부 인권과 저항권을 담았어요.","keywords":["독립 선언"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t5","kind":"term","title":"인권 선언","text":"1789년 프랑스 국민 의회가 발표한 선언으로, 사람의 자유와 평등, 국민 주권을 밝혔어요.","keywords":["인권 선언"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t6","kind":"term","title":"구제도","text":"프랑스 혁명 이전, 성직자·귀족이 특권을 누리고 평민이 세금을 떠맡던 불평등한 사회 체제예요.","keywords":["구제도"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t7","kind":"term","title":"크리오요","text":"라틴 아메리카 식민지에서 태어난 백인이에요. 라틴 아메리카 독립 운동에 앞장섰어요.","keywords":["크리오요"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t8","kind":"term","title":"국민 국가","text":"같은 국민이라는 의식을 가진 사람들이 하나의 정부 아래 뭉쳐 이룬 나라예요.","keywords":["국민 국가"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#t9","kind":"term","title":"참정권","text":"국민이 나라의 정치에 참여할 수 있는 권리예요. 투표할 권리(선거권)가 대표적이에요.","keywords":["참정권"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#f0","kind":"faq","title":"혁명이라고 하면 꼭 싸움이 있어야 해요?","text":"아니에요. 혁명은 사회의 질서나 제도를 근본부터 바꾸는 일을 말해요. 영국의 명예혁명처럼 피를 거의 흘리지 않고 이루어진 혁명도 있어요. 다만 미국 혁명, 프랑스 혁명처럼 전쟁과 큰 희생이 따른 경우도 많았어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#f1","kind":"faq","title":"입헌 군주제랑 공화정은 뭐가 달라요?","text":"입헌 군주제는 왕이 있지만 헌법과 의회에 따라 다스리는 체제예요(명예혁명 뒤의 영국). 공화정은 왕이 없고 국민이 뽑은 대표가 나라를 이끄는 체제예요(미국, 혁명기의 프랑스).","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#f2","kind":"faq","title":"민족주의는 좋은 거예요, 나쁜 거예요?","text":"민족주의는 외국의 지배에 맞서 독립하거나 흩어진 사람들이 하나의 나라를 이루는 힘이 되었어요. 하지만 다른 민족을 깔보거나 공격하는 쪽으로 흐르면 큰 갈등을 낳기도 했어요. 어떻게 쓰이느냐에 따라 결과가 달라졌다고 이해하면 돼요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#m0","kind":"mistake","title":"자주 하는 실수","text":"청교도 혁명과 명예혁명을 헷갈리는 실수 — 크롬웰이 왕을 처형한 것은 청교도 혁명, 피를 흘리지 않고 왕을 바꾼 것은 1688년 명예혁명이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#m1","kind":"mistake","title":"자주 하는 실수","text":"권리 장전(영국), 독립 선언(미국), 인권 선언(프랑스)을 섞어 쓰는 실수 — 나라와 문서를 짝지어 기억해요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-08#m2","kind":"mistake","title":"자주 하는 실수","text":"시민 혁명으로 곧바로 모든 사람이 투표하게 되었다고 생각하는 실수 — 처음에는 재산 있는 남성 중심이었고, 참정권은 오랜 운동으로 넓어졌어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-08","grade":"m2"},
{"id":"hist-m-1-09","kind":"unit","title":"산업화와 제국주의","text":"산업 혁명이 가져온 변화와 제국주의 침략, 이에 맞서 근대 국가를 세우려 한 아시아의 노력을 알아봐요. 산업 혁명의 전개 과정과 그것이 가져온 사회 변화(자본주의, 노동·도시 문제, 사회주의)를 설명할 수 있어요. 제국주의가 나타난 까닭과 열강의 아시아·아프리카 침략 과정을 설명할 수 있어요. 오스만 제국·인도·청·일본이 펼친 개혁과 민족 운동을 정리할 …","keywords":["산업 혁명","자본주의","사회주의","제국주의","사회 진화론","탄지마트","세포이 항쟁","양무운동","신해혁명","메이지 유신"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#c0","kind":"concept","title":"산업 혁명과 자본주의의 발달","text":"산업 혁명은 18세기 후반 영국에서 시작된 큰 변화로, 사람의 손과 도구로 하던 생산이 기계를 쓰는 공장 생산으로 바뀐 것을 말해요. 영국에서 먼저 일어난 까닭은 여러 조건이 갖추어져 있었기 때문이에요. 기계를 만들고 돌리는 데 필요한 석탄과 철이 풍부했어요. 인클로저 운동(지주가 땅에","keywords":["산업 혁명","자본주의"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#c1","kind":"concept","title":"산업화의 그늘과 사회주의의 등장","text":"산업화로 물건은 풍부해졌지만 새로운 문제도 생겼어요. 문제 · 모습 노동 문제 · 하루 12시간이 넘는 긴 노동, 낮은 임금, 위험한 작업 환경, 어린이 노동 도시 문제 · 공장이 있는 도시로 사람이 몰려 집이 모자라고 빈민가가 생김. 상하수도가 부족해 콜레라 같은 전염병이 돎 환경 변","keywords":["자본주의","사회주의"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#c2","kind":"concept","title":"제국주의와 아시아·아프리카 분할","text":"19세기 후반 산업화한 나라들은 공장에 필요한 원료, 만든 상품을 팔 시장, 남는 자본을 투자할 곳을 찾아 다른 지역을 식민지로 삼으려고 경쟁했어요. 이렇게 군사력을 앞세워 다른 나라나 지역을 지배하려는 정책을 제국주의라고 하고, 이런 정책을 편 강대국들을 열강이라고 해요. 열강은 사회","keywords":["제국주의","사회 진화론"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#c3","kind":"concept","title":"서아시아와 인도의 개혁과 민족 운동","text":"오스만 제국은 유럽 열강의 압박과 제국 안 여러 민족의 독립 운동으로 흔들렸어요. 그래서 1839년부터 행정·군사·교육·법을 서양식으로 고치는 탄지마트 개혁을 펼쳤어요. 1876년에는 의회를 두는 미드하트 헌법을 만들었지만, 술탄이 러시아와의 전쟁을 구실로 곧 헌법을 멈추었어요. 이에 ","keywords":["탄지마트","세포이 항쟁"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#c4","kind":"concept","title":"청의 근대화 운동","text":"청은 아편 전쟁(1840~1842년)에서 영국에 지고 난징 조약을 맺어 홍콩을 내주고 항구를 열었어요. 이어 제2차 아편 전쟁에서도 져 서양 세력이 더 깊이 들어왔어요. 나라 안에서는 홍수전이 이끈 태평천국 운동(1851~1864년)이 일어나 청을 크게 흔들었어요. 운동 · 때 · 중심","keywords":["양무운동","메이지 유신"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#c5","kind":"concept","title":"일본의 메이지 유신과 근대화 비교","text":"일본은 1853년 미국 페리 함대의 압력을 받고 이듬해 문호를 열었어요. 서양과 불평등 조약을 맺자 막부(무사 정권)에 대한 불만이 커졌고, 1868년 막부를 무너뜨리고 천황 중심의 새 정부를 세웠어요. 이 정부가 추진한 개혁을 메이지 유신이라고 해요. 지방의 번을 없애고 현을 두어 중","keywords":["제국주의","메이지 유신"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t0","kind":"term","title":"산업 혁명","text":"18세기 후반 영국에서 시작되어, 손으로 하던 생산이 기계를 쓰는 공장 생산으로 바뀐 큰 변화예요.","keywords":["산업 혁명"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t1","kind":"term","title":"자본주의","text":"공장·기계 같은 생산 수단을 가진 자본가가 노동자를 고용해 이윤을 얻으려고 상품을 생산하는 경제 체제예요.","keywords":["자본주의"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t2","kind":"term","title":"사회주의","text":"생산 수단을 사회가 함께 소유하고 관리하여 평등한 사회를 만들자는 사상이에요. 마르크스·엥겔스의 『공산당 선언』(1848년)이 대표적이에요.","keywords":["사회주의"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t3","kind":"term","title":"제국주의","text":"19세기 후반 열강이 원료·시장·투자처를 얻으려고 군사력을 앞세워 다른 지역을 식민지로 삼은 정책이에요.","keywords":["제국주의"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t4","kind":"term","title":"사회 진화론","text":"강한 민족이 약한 민족을 지배하는 것이 자연스럽다는 주장이에요. 열강이 침략을 정당화하는 데 썼고, 오늘날에는 근거 없는 차별로 평가해요.","keywords":["사회 진화론"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t5","kind":"term","title":"탄지마트","text":"오스만 제국이 1839년부터 펼친 서양식 개혁이에요. 행정·군사·교육·법 제도를 고쳤어요.","keywords":["탄지마트"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t6","kind":"term","title":"세포이 항쟁","text":"1857년 영국 동인도 회사에 고용된 인도인 병사(세포이)들이 일으킨 반영 항쟁이에요. 진압된 뒤 영국이 인도를 직접 다스렸어요.","keywords":["세포이 항쟁"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t7","kind":"term","title":"양무운동","text":"1860년대부터 청이 펼친 근대화 운동이에요. 전통 체제는 지키고 서양 기술만 받아들이자는 중체서용을 내걸었어요.","keywords":["양무운동"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t8","kind":"term","title":"신해혁명","text":"1911년 쑨원 등이 삼민주의를 내걸고 일으켜 청을 무너뜨린 혁명이에요. 1912년 중화민국이 세워졌어요.","keywords":["신해혁명"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#t9","kind":"term","title":"메이지 유신","text":"1868년 일본에서 막부를 무너뜨리고 천황 중심의 정부가 추진한 근대화 개혁이에요.","keywords":["메이지 유신"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#f0","kind":"faq","title":"왜 하필 영국에서 산업 혁명이 먼저 일어났어요?","text":"영국에는 산업 혁명에 필요한 조건이 한꺼번에 갖추어져 있었어요. 석탄과 철이 풍부했고, 인클로저 운동으로 땅을 잃은 농민들이 도시로 몰려 노동력이 넉넉했어요. 또 무역과 식민지로 모은 자본과 상품을 팔 넓은 시장이 있었지요.","keywords":["산업 혁명"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#f1","kind":"faq","title":"제국주의 나라들은 왜 침략이 옳다고 생각했어요?","text":"열강은 사회 진화론과 인종주의를 내세워 \"강한 민족이 약한 민족을 이끄는 것이 당연하다\", \"문명을 전해 준다\"고 주장했어요. 하지만 이것은 원료와 시장을 얻으려는 침략을 그럴듯하게 꾸민 말이었어요. 오늘날에는 과학적 근거가 없는 차별적 주장으로 평가해요.","keywords":["제국주의"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#f2","kind":"faq","title":"양무운동이랑 변법자강 운동은 뭐가 달라요?","text":"양무운동은 \"전통 체제는 그대로, 서양 기술만\" 받아들이자는 운동(중체서용)이었어요. 변법자강 운동은 기술만으로는 부족하다며 일본의 메이지 유신처럼 정치 제도까지 바꾸어 입헌 군주제를 세우려 했어요. 양무운동은 청일 전쟁 패배로, 변법자강 운동은 보수파의 반대로 한계를 드러냈어요.","keywords":["양무운동"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#f3","kind":"faq","title":"일본은 어떻게 다른 아시아 나라보다 빨리 근대화했어요?","text":"막부를 무너뜨린 새 정부가 중앙 집권을 강화하고, 신분제 개혁·징병제·산업 육성·헌법 제정처럼 제도 전체를 위에서부터 빠르게 바꾸었기 때문이에요. 하지만 일본은 그 힘으로 서양 열강처럼 이웃 나라를 침략했어요. 근대화의 성과와 함께 이 점을 꼭 같이 기억해야 해요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#m0","kind":"mistake","title":"자주 하는 실수","text":"양무운동과 변법자강 운동을 헷갈리는 실수 — 양무운동은 기술만(중체서용), 변법자강 운동은 정치 제도까지(입헌 군주제) 바꾸려 했어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#m1","kind":"mistake","title":"자주 하는 실수","text":"세포이 항쟁 뒤 인도가 독립했다고 생각하는 실수 — 항쟁은 진압되었고, 오히려 영국 정부가 인도를 직접 다스리게 되었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-09#m2","kind":"mistake","title":"자주 하는 실수","text":"영국의 종단 정책과 프랑스의 횡단 정책을 바꾸어 기억하는 실수 — 영국은 카이로~케이프타운(남북), 프랑스는 서아프리카에서 동쪽(동서)이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-09","grade":"m2"},
{"id":"hist-m-1-10","kind":"unit","title":"제1차 세계 대전과 민족 운동","text":"제1차 세계 대전과 러시아 혁명 뒤 달라진 세계 질서, 아시아·아프리카에서 일어난 민족 운동을 배워요. 제1차 세계 대전의 배경과 총력전의 모습을 설명할 수 있어요. 러시아 혁명의 과정과 소련이 세워진 과정을 정리할 수 있어요. 베르사유 체제와 국제 연맹, 전쟁 뒤 민주주의의 확대를 설명할 수 있어요. 아시아·서아시아·아프리카에서 일어난 민족 운동을 비교…","keywords":["3국 동맹","3국 협상","총력전","러시아 혁명","민족 자결주의","베르사유 체제","국제 연맹","보통 선거","비폭력·불복종 운동","5·4 운동"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#c0","kind":"concept","title":"제1차 세계 대전의 배경과 총력전","text":"19세기 말부터 유럽 열강은 식민지와 세력권을 놓고 크게 대립했어요. 독일·오스트리아·이탈리아는 3국 동맹(1882년)을, 영국·프랑스·러시아는 3국 협상(1907년)을 맺어 두 진영으로 갈라졌어요. 특히 발칸반도는 오스트리아·독일이 앞세운 범게르만주의와 러시아·세르비아가 앞세운 범슬라","keywords":["3국 동맹","3국 협상","총력전"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#c1","kind":"concept","title":"러시아 혁명과 소련의 성립","text":"러시아는 황제(차르)가 강한 권력을 쥔 나라였어요. 전쟁이 길어지자 식량이 모자라고 패전이 이어져 민중의 불만이 폭발했어요. 3월 혁명(1917년): 노동자와 병사들이 일어나 황제 니콜라이 2세가 물러나고 임시 정부가 세워졌어요. 그러나 임시 정부는 전쟁을 계속했어요. 11월 혁명(19","keywords":["러시아 혁명"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#c2","kind":"concept","title":"베르사유 체제와 국제 연맹","text":"전쟁이 끝난 뒤 1919년 승전국들은 파리 강화 회의를 열었어요. 회의는 미국 대통령 윌슨이 내놓은 14개조 평화 원칙을 바탕으로 했는데, 그 핵심이 민족 자결주의예요. 민족 자결주의란 각 민족이 자기 나라의 운명을 스스로 결정해야 한다는 원칙이에요. 패전국 독일과는 베르사유 조약을 맺","keywords":["민족 자결주의","베르사유 체제","국제 연맹"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#c3","kind":"concept","title":"전쟁 이후 민주주의의 확대","text":"총력전에서는 노동자와 여성도 공장과 사회 곳곳에서 전쟁을 떠받쳤어요. \"함께 희생했으니 정치에 참여할 권리도 함께 누려야 한다\"는 목소리가 커졌고, 전쟁이 끝난 뒤 민주주의가 확대되었어요. 나라 · 변화 영국 · 1918년 선거법을 고쳐 일정한 나이가 넘은 여성에게 선거권을 주었고, 1","keywords":["총력전","보통 선거"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#c4","kind":"concept","title":"동아시아와 인도의 민족 운동","text":"민족 자결주의와 러시아 혁명의 영향을 받아, 1919년 무렵 아시아 곳곳에서 민족 운동이 크게 일어났어요. 한국: 1919년 일제의 식민 통치에 맞서 전국에서 만세 시위를 벌인 3·1 운동이 일어났어요. 이를 계기로 같은 해 대한민국 임시 정부가 세워졌어요. 중국: 파리 강화 회의가 독","keywords":["러시아 혁명","민족 자결주의","5·4 운동"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#c5","kind":"concept","title":"서아시아·아프리카의 민족 운동과 새로운 사상","text":"패전국이 된 오스만 제국은 영토가 크게 줄고 연합국에 점령당할 위기에 놓였어요. 이때 무스타파 케말이 저항을 이끌어 외국 군대를 물리치고, 술탄 제도를 없앤 뒤 1923년 튀르키예 공화국을 세웠어요. 그는 이슬람교와 정치를 나누고(정교 분리), 아랍 문자 대신 로마자를 쓰게 하고, 여성","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t0","kind":"term","title":"3국 동맹","text":"1882년 독일·오스트리아·이탈리아가 맺은 동맹이에요. 3국 협상과 맞섰어요.","keywords":["3국 동맹"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t1","kind":"term","title":"3국 협상","text":"1907년 영국·프랑스·러시아가 이룬 협력 관계예요. 3국 동맹과 맞섰어요.","keywords":["3국 협상"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t2","kind":"term","title":"총력전","text":"군대뿐 아니라 나라의 모든 사람·물자·산업을 동원하는 전쟁이에요. 제1차 세계 대전이 대표적이에요.","keywords":["총력전"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t3","kind":"term","title":"러시아 혁명","text":"1917년 러시아에서 일어난 혁명이에요. 3월 혁명으로 황제가 물러났고, 11월 혁명으로 레닌의 소비에트 정부가 세워졌어요.","keywords":["러시아 혁명"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t4","kind":"term","title":"민족 자결주의","text":"각 민족이 자기 나라의 운명을 스스로 결정해야 한다는 원칙이에요. 윌슨의 14개조 평화 원칙에 담겼어요.","keywords":["민족 자결주의"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t5","kind":"term","title":"베르사유 체제","text":"1919년 베르사유 조약을 바탕으로 짜인 제1차 세계 대전 뒤의 국제 질서예요.","keywords":["베르사유 체제"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t6","kind":"term","title":"국제 연맹","text":"1920년 세계 평화를 지키려고 만든 첫 국제 평화 기구예요. 미국이 가입하지 않았고 군대가 없다는 한계가 있었어요.","keywords":["국제 연맹"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t7","kind":"term","title":"보통 선거","text":"재산·성별·신분에 상관없이 일정한 나이가 된 모든 국민이 투표하는 제도예요.","keywords":["보통 선거"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t8","kind":"term","title":"비폭력·불복종 운동","text":"간디가 이끈 인도의 민족 운동 방법이에요. 폭력을 쓰지 않으면서 영국의 부당한 법과 명령을 따르지 않았어요.","keywords":["비폭력·불복종 운동"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#t9","kind":"term","title":"5·4 운동","text":"1919년 파리 강화 회의가 산둥반도의 이권을 일본에 넘기자, 베이징 학생들을 중심으로 일어난 중국의 반제국주의 운동이에요.","keywords":["5·4 운동"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#f0","kind":"faq","title":"3·1 운동이랑 5·4 운동은 관계가 있어요?","text":"둘 다 1919년에 일어난 아시아의 대표적인 민족 운동이에요. 3·1 운동은 3월에 한국에서, 5·4 운동은 5월에 중국에서 일어났어요. 3·1 운동이 중국의 5·4 운동 등 아시아의 민족 운동에 영향을 주었다고 평가돼요.","keywords":["5·4 운동"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#f1","kind":"faq","title":"러시아 혁명을 왜 2월 혁명, 10월 혁명이라고도 해요?","text":"당시 러시아는 다른 나라와 다른 달력(율리우스력)을 썼어요. 그 달력으로는 2월과 10월이었고, 오늘날 우리가 쓰는 달력으로는 3월과 11월이에요. 같은 사건을 다른 달력으로 부른 것이에요.","keywords":["러시아 혁명"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#f2","kind":"faq","title":"국제 연맹이 있었는데 왜 또 세계 대전이 일어났어요?","text":"국제 연맹은 침략한 나라를 막을 군대가 없었고, 미국이 가입하지 않아 힘이 약했어요. 그래서 침략 전쟁이 일어나도 말로 비판하거나 경제 제재를 하는 것밖에 할 수 없었어요. 이 한계를 반성해 제2차 세계 대전 뒤에는 국제 연합(UN)을 만들었어요.","keywords":["국제 연맹"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#f3","kind":"faq","title":"민족 자결주의가 발표됐는데 왜 한국은 독립하지 못했어요?","text":"민족 자결주의는 패전국의 지배를 받던 지역에만 적용되었어요. 한국을 지배한 일본은 승전국 쪽이었기 때문에 한국에는 적용되지 않았어요. 그래도 이 원칙은 한국 사람들에게 큰 자극이 되어 3·1 운동이 일어나는 배경이 되었어요.","keywords":["민족 자결주의"],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#m0","kind":"mistake","title":"자주 하는 실수","text":"3월 혁명과 11월 혁명을 헷갈리는 실수 — 3월 혁명은 황제를 몰아내고 임시 정부를, 11월 혁명은 레닌이 소비에트 정부를 세웠어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#m1","kind":"mistake","title":"자주 하는 실수","text":"국제 연맹(1920년)과 국제 연합(1945년)을 헷갈리는 실수 — 제1차 세계 대전 뒤에 만든 것이 국제 연맹이고, 군대가 없다는 한계가 있었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-10#m2","kind":"mistake","title":"자주 하는 실수","text":"민족 자결주의로 모든 식민지가 독립했다고 생각하는 실수 — 패전국의 지배를 받던 지역에만 적용되었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-10","grade":"m2"},
{"id":"hist-m-1-11","kind":"unit","title":"제2차 세계 대전과 평화","text":"대공황과 전체주의의 등장, 제2차 세계 대전의 전개와 전쟁 범죄, 평화를 지키려는 노력을 살펴봐요. 세계 대공황의 원인과 각국의 대응(뉴딜 정책, 블록 경제)을 설명할 수 있어요. 전체주의가 등장한 배경과 특징을 설명할 수 있어요. 제2차 세계 대전의 전개 과정과 결과를 정리할 수 있어요. 전쟁 중의 인권 침해를 알고, 평화와 인권을 회복하려는 노력을 설…","keywords":["세계 대공황","뉴딜 정책","블록 경제","전체주의","나치즘","추축국","태평양 전쟁","홀로코스트","국제 연합(UN)","세계 인권 선언"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#c0","kind":"concept","title":"세계 대공황과 각국의 대응","text":"제1차 세계 대전 뒤 미국은 큰 호황을 누렸어요. 그런데 공장에서는 물건을 계속 많이 만들었지만, 사람들이 살 수 있는 양은 그만큼 늘지 않았어요(과잉 생산). 결국 1929년 10월 미국 뉴욕의 주식 시장에서 주가가 크게 떨어지면서 기업과 은행이 잇따라 망하고 실업자가 크게 늘었어요.","keywords":["세계 대공황","뉴딜 정책","블록 경제"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#c1","kind":"concept","title":"전체주의의 등장","text":"전체주의는 개인보다 국가나 민족을 앞세워 개인의 자유와 권리를 억누르는 사상과 체제예요. 한 사람이나 한 정당이 권력을 독차지하고(독재), 언론과 교육을 통제하며, 반대하는 사람을 탄압하고, 다른 나라를 침략했어요. 대공황으로 생활이 어려워지고 사회가 불안해지자, 강한 지도자가 문제를 ","keywords":["전체주의","나치즘"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#c2","kind":"concept","title":"제2차 세계 대전의 시작과 확대","text":"독일은 오스트리아를 합병한 뒤 체코슬로바키아의 일부도 차지했어요. 영국과 프랑스는 전쟁을 피하려고 독일의 요구를 들어주었어요(유화 정책). 1939년 8월 독일은 소련과 불가침 조약을 맺어 동쪽의 걱정을 덜어 낸 뒤, 1939년 9월 1일 폴란드를 침공했어요. 그러자 영국과 프랑스가 독","keywords":["태평양 전쟁"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#c3","kind":"concept","title":"연합국의 반격과 전쟁의 끝","text":"1942년 무렵부터 전세가 바뀌었어요. 태평양: 미국이 1942년 미드웨이 해전에서 일본 해군을 크게 무찔렀어요. 유럽: 소련이 스탈린그라드 전투(1942~1943년)에서 독일군을 물리쳤고, 1943년 이탈리아가 항복했어요. 1944년 6월 연합군이 프랑스 북부 해안에 상륙한 노르망디 ","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#c4","kind":"concept","title":"전쟁 중의 학살과 인권 침해","text":"제2차 세계 대전 중에는 군인뿐 아니라 수많은 민간인이 학살당하고 인권을 짓밟혔어요. 이런 일을 기억하는 것은 다시는 되풀이하지 않기 위해서예요. 홀로코스트: 나치 독일은 유대인을 \"열등한 민족\"이라고 몰아 강제 수용소에 가두고, 약 600만 명을 학살했어요. 아우슈비츠가 대표적인 수용","keywords":["홀로코스트"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#c5","kind":"concept","title":"평화와 인권 회복을 위한 노력","text":"전쟁이 끝난 뒤 세계는 다시는 이런 비극이 없도록 여러 노력을 기울였어요. 국제 연합(UN): 1945년 10월 세계 평화와 안전을 지키려고 만들어졌어요. 안전 보장 이사회가 침략에 대해 결정을 내리고, 필요하면 군대를 보내 제재할 수도 있어요. 미국·소련 같은 강대국이 처음부터 참여하","keywords":["국제 연합(UN)","세계 인권 선언"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t0","kind":"term","title":"세계 대공황","text":"1929년 미국 뉴욕의 주가 폭락에서 시작되어 전 세계로 퍼진 큰 경제 불황이에요.","keywords":["세계 대공황"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t1","kind":"term","title":"뉴딜 정책","text":"대공황에 맞서 미국 루스벨트 대통령이 펼친 정책이에요. 정부가 공공사업으로 일자리를 만들고 사회 보장 제도를 마련했어요.","keywords":["뉴딜 정책"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t2","kind":"term","title":"블록 경제","text":"영국·프랑스가 본국과 식민지를 하나의 경제권으로 묶고, 다른 나라 상품에 높은 관세를 매긴 정책이에요.","keywords":["블록 경제"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t3","kind":"term","title":"전체주의","text":"개인보다 국가·민족을 앞세워 개인의 자유와 권리를 억누르는 사상과 체제예요. 파시즘·나치즘·일본 군국주의가 대표적이에요.","keywords":["전체주의"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t4","kind":"term","title":"나치즘","text":"히틀러가 이끈 독일 나치당의 전체주의예요. 독재와 침략, 유대인 차별·학살을 저질렀어요.","keywords":["나치즘"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t5","kind":"term","title":"추축국","text":"제2차 세계 대전에서 연합국과 맞선 독일·이탈리아·일본을 말해요.","keywords":["추축국"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t6","kind":"term","title":"태평양 전쟁","text":"1941년 12월 일본이 하와이 진주만을 기습 공격하면서 시작된, 일본과 미국 등 연합국 사이의 전쟁이에요.","keywords":["태평양 전쟁"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t7","kind":"term","title":"홀로코스트","text":"나치 독일이 유대인 약 600만 명을 강제 수용소에 가두고 학살한 일이에요.","keywords":["홀로코스트"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t8","kind":"term","title":"국제 연합(UN)","text":"1945년 세계 평화와 안전을 지키려고 만든 국제기구예요. 안전 보장 이사회가 군대를 보내 제재할 수도 있어요.","keywords":["국제 연합(UN)"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#t9","kind":"term","title":"세계 인권 선언","text":"1948년 국제 연합 총회에서 채택된 선언이에요. 모든 사람은 태어날 때부터 자유롭고 존엄하며 평등하다고 밝혔어요.","keywords":["세계 인권 선언"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#f0","kind":"faq","title":"미국에서 시작된 불황이 왜 세계 전체로 퍼졌어요?","text":"제1차 세계 대전 뒤 유럽 여러 나라는 전쟁 피해를 복구하느라 미국의 돈을 빌리고 미국에 물건을 팔며 경제를 꾸렸어요. 미국 경제가 무너지자 미국이 돈을 거두어들이고 물건도 사지 않게 되어, 미국에 기대던 나라들이 함께 어려워졌어요. 게다가 각 나라가 자기 경제를 지키려고 무역을 막으면서 불황이 더 깊어졌어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#f1","kind":"faq","title":"국제 연맹이랑 국제 연합은 뭐가 달라요?","text":"국제 연맹은 제1차 세계 대전 뒤(1920년), 국제 연합은 제2차 세계 대전 뒤(1945년)에 만들어졌어요. 국제 연맹은 미국이 빠지고 군대가 없어 침략을 막지 못했어요. 국제 연합은 강대국이 처음부터 참여하고, 안전 보장 이사회가 군대를 보내 제재할 수 있게 해서 그 한계를 보완했어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#f2","kind":"faq","title":"제2차 세계 대전은 언제 시작해서 언제 끝났어요?","text":"1939년 9월 독일이 폴란드를 침공하면서 시작되었어요. 1945년 5월 독일이, 8월 15일 일본이 항복을 발표하면서 끝났어요. 아시아에서는 1937년 중일 전쟁부터 이미 전쟁이 이어지고 있었다는 점도 함께 기억해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#f3","kind":"faq","title":"홀로코스트 같은 슬픈 일을 왜 배워야 해요?","text":"이런 일은 갑자기 생긴 것이 아니라, 특정한 사람들을 차별하는 말과 법이 조금씩 쌓이면서 일어났어요. 그 과정을 알아야 비슷한 조짐을 알아채고 막을 수 있어요. 그리고 희생된 사람들을 기억하는 것은 그들의 존엄을 지키는 일이기도 해요.","keywords":["홀로코스트"],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#m0","kind":"mistake","title":"자주 하는 실수","text":"진주만 공격으로 제2차 세계 대전이 시작되었다고 생각하는 실수 — 진주만 공격(1941년)은 태평양 전쟁의 시작이고, 제2차 세계 대전은 1939년 독일의 폴란드 침공으로 시작되었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#m1","kind":"mistake","title":"자주 하는 실수","text":"뉴딜 정책과 블록 경제를 헷갈리는 실수 — 뉴딜은 미국 정부가 일자리를 만든 정책, 블록 경제는 영국·프랑스가 식민지와 묶은 정책이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-11#m2","kind":"mistake","title":"자주 하는 실수","text":"국제 연맹과 국제 연합을 헷갈리는 실수 — 무력 제재 수단을 갖춘 것은 1945년에 만든 국제 연합이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-11","grade":"m2"},
{"id":"hist-m-1-12","kind":"unit","title":"냉전과 오늘날의 세계","text":"냉전과 제3 세계의 등장, 냉전이 끝난 뒤의 변화, 민주주의·인권을 위한 노력과 세계화의 성과와 과제를 알아봐요. 냉전 체제가 만들어진 과정과 냉전 속에서 일어난 전쟁을 설명할 수 있어요. 제3 세계의 등장과 냉전이 완화되고 끝난 과정을 정리할 수 있어요. 20세기 후반 민주주의와 인권을 위한 여러 운동을 설명할 수 있어요. 세계화의 성과와 과제를 알고,…","keywords":["냉전","북대서양 조약 기구(NATO)","제3 세계","비동맹 운동","닉슨 독트린","베를린 장벽","아파르트헤이트","세계화","유럽 연합(EU)","파리 협정"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#c0","kind":"concept","title":"냉전 체제의 형성과 6·25 전쟁","text":"제2차 세계 대전 뒤 세계는 미국 중심의 자본주의(자유주의) 진영과 소련 중심의 공산주의(사회주의) 진영으로 나뉘었어요. 두 진영은 직접 전쟁을 벌이지는 않았지만 정치·경제·군사·이념 등 모든 면에서 날카롭게 대립했어요. 이것을 총소리 없는 전쟁이라는 뜻으로 냉전이라고 해요. · 자본주","keywords":["냉전"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#c1","kind":"concept","title":"제3 세계의 등장과 비동맹 운동","text":"제2차 세계 대전 뒤 아시아와 아프리카에서 많은 나라가 식민지에서 벗어나 독립했어요. 인도·인도네시아 등이 독립했고, 1960년에는 아프리카에서만 17개 나라가 한꺼번에 독립해 이 해를 \"아프리카의 해\"라고 불러요. 새로 독립한 나라들 가운데 상당수는 미국 편에도 소련 편에도 서지 않고","keywords":["제3 세계","비동맹 운동"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#c2","kind":"concept","title":"베트남 전쟁과 냉전의 완화","text":"베트남은 제2차 세계 대전이 끝나자 호찌민을 중심으로 독립을 선언했어요. 다시 지배하려는 프랑스와 전쟁을 벌여 1954년 승리했지만, 제네바 협정으로 북위 17도선을 경계로 남북이 나뉘었어요. 공산주의 확산을 막으려던 미국은 남베트남을 지원하다가 1960년대 중반부터 대규모 군대를 보내","keywords":["냉전"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#c3","kind":"concept","title":"냉전의 종식: 독일 통일과 소련 해체","text":"1980년대 소련은 공산당 독재와 계획 경제의 한계로 경제가 크게 어려워졌어요. 1985년 소련 지도자가 된 고르바초프는 개혁(페레스트로이카)과 개방(글라스노스트) 정책을 펴서 시장 경제를 일부 받아들이고 언론의 자유를 넓혔어요. 또 미국과 군비 축소에 합의하고, 동유럽 나라들의 일에 ","keywords":["냉전","베를린 장벽"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#c4","kind":"concept","title":"민주주의와 인권을 위한 운동","text":"20세기 후반 세계 곳곳에서 더 많은 사람의 자유와 평등, 인권을 위한 운동이 일어났어요. 민권 운동: 미국에서는 흑인에 대한 차별이 법과 제도로 남아 있었어요. 1955년 버스 좌석 차별에 맞선 몽고메리 버스 승차 거부 운동을 계기로, 마틴 루서 킹 목사가 비폭력 운동을 이끌었어요. ","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#c5","kind":"concept","title":"세계화의 성과와 과제","text":"냉전이 끝난 뒤 사람·상품·돈·정보가 나라의 경계를 넘어 자유롭게 오가는 세계화가 빠르게 이루어졌어요. 1995년에는 자유 무역을 넓히려고 세계 무역 기구(WTO)가 출범했어요. 성과 지역 통합: 이웃 나라들끼리 경제·정치 협력체를 만들었어요. 유럽에서는 1993년 유럽 연합(EU)이 ","keywords":["냉전","세계화","유럽 연합(EU)"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t0","kind":"term","title":"냉전","text":"제2차 세계 대전 뒤 미국 중심의 자본주의 진영과 소련 중심의 공산주의 진영이 직접 전쟁 없이 날카롭게 대립한 상태예요.","keywords":["냉전"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t1","kind":"term","title":"북대서양 조약 기구(NATO)","text":"1949년 미국과 서유럽 나라들이 만든 군사 동맹이에요. 공산주의 진영은 바르샤바 조약 기구(1955년)로 맞섰어요.","keywords":["북대서양 조약 기구(NATO)"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t2","kind":"term","title":"제3 세계","text":"냉전 시기 어느 진영에도 속하지 않고 중립을 지키려 한 나라들이에요. 주로 새로 독립한 아시아·아프리카 나라들이에요.","keywords":["제3 세계"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t3","kind":"term","title":"비동맹 운동","text":"어느 강대국과도 동맹을 맺지 않고 평화 공존을 추구한 제3 세계의 운동이에요. 1961년 비동맹 회의로 본격화되었어요.","keywords":["비동맹 운동"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t4","kind":"term","title":"닉슨 독트린","text":"1969년 미국 닉슨 대통령이 아시아 나라들의 안보는 스스로 책임지라며 미국의 군사 개입을 줄이겠다고 밝힌 선언이에요.","keywords":["닉슨 독트린"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t5","kind":"term","title":"베를린 장벽","text":"동서 베를린을 가르던 장벽이에요. 1989년 11월 무너져 냉전 종식과 독일 통일의 상징이 되었어요.","keywords":["베를린 장벽"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t6","kind":"term","title":"아파르트헤이트","text":"남아프리카 공화국에서 백인과 유색인을 나누어 차별한 인종 분리 정책이에요. 오랜 저항 끝에 폐지되었어요.","keywords":["아파르트헤이트"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t7","kind":"term","title":"세계화","text":"사람·상품·돈·정보가 나라의 경계를 넘어 자유롭게 오가며 세계가 하나로 이어지는 현상이에요.","keywords":["세계화"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t8","kind":"term","title":"유럽 연합(EU)","text":"1993년 출범한 유럽의 지역 통합 기구예요. 많은 회원국이 공동 화폐 유로를 써요.","keywords":["유럽 연합(EU)"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#t9","kind":"term","title":"파리 협정","text":"2015년 기후 위기에 대응하려고 맺은 국제 협정이에요. 선진국과 개발 도상국이 모두 온실가스를 줄이기로 했어요.","keywords":["파리 협정"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#f0","kind":"faq","title":"냉전은 왜 \"차가운 전쟁\"이라고 해요?","text":"미국과 소련이 서로 직접 총을 쏘며 싸우지는 않았지만, 전쟁만큼이나 날카롭게 대립했기 때문이에요. 총소리가 나는 \"뜨거운 전쟁\"과 구별해 차가운 전쟁, 곧 냉전이라고 불러요. 다만 한반도의 6·25 전쟁이나 베트남 전쟁처럼 냉전이 실제 전쟁으로 터진 곳도 있었어요.","keywords":["냉전"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#f1","kind":"faq","title":"제3 세계는 가난한 나라라는 뜻이에요?","text":"처음에는 미국 중심의 진영(제1 세계)과 소련 중심의 진영(제2 세계) 어디에도 속하지 않은 나라들을 가리키는 말이었어요. 이 나라들 가운데 개발 도상국이 많아서 나중에는 개발 도상국을 뜻하는 말로도 쓰였어요. 역사에서 배울 때는 \"비동맹 중립을 내세운 나라들\"이라는 뜻으로 기억하세요.","keywords":["제3 세계"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#f2","kind":"faq","title":"냉전이 끝났는데 한반도는 왜 아직 나뉘어 있어요?","text":"독일은 냉전이 끝날 무렵 통일되었지만, 한반도는 6·25 전쟁을 겪으며 분단이 깊이 굳어졌어요. 전쟁은 1953년 정전 협정으로 전투만 멈춘 상태로 이어져 왔어요. 남북 관계와 통일 노력은 역사②의 마지막 단원에서 더 배워요.","keywords":["냉전"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#f3","kind":"faq","title":"세계화는 좋은 거예요, 나쁜 거예요?","text":"두 얼굴이 있어요. 다양한 물건과 문화를 누리고 과학 기술의 혜택을 나누게 된 것은 성과예요. 하지만 나라 사이·나라 안의 빈부 격차가 커지고, 문화가 획일화될 수 있다는 걱정도 있어요. 그래서 세계화의 성과는 넓히고 과제는 함께 해결하려는 노력이 중요해요.","keywords":["세계화"],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#m0","kind":"mistake","title":"자주 하는 실수","text":"트루먼 독트린과 닉슨 독트린을 헷갈리는 실수 — 트루먼 독트린(1947년)은 냉전을 본격화했고, 닉슨 독트린(1969년)은 냉전 완화의 계기가 되었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#m1","kind":"mistake","title":"자주 하는 실수","text":"소련이 해체된 뒤에 독일이 통일되었다고 생각하는 실수 — 독일 통일(1990년)이 먼저이고, 소련 해체(1991년)가 그 뒤예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-1-12#m2","kind":"mistake","title":"자주 하는 실수","text":"베트남을 나눈 17도선과 한반도를 나눈 38도선을 헷갈리는 실수 — 베트남은 북위 17도선, 한반도는 북위 38도선이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-1","unit":"hist-m-1-12","grade":"m2"},
{"id":"hist-m-2-01","kind":"unit","title":"고조선과 여러 나라","text":"청동기 문화를 바탕으로 세워진 고조선과, 고조선이 무너진 뒤 자라난 여러 나라의 모습을 알아봐요. 청동기 시대에 벼농사와 계급, 군장이 나타난 까닭을 설명할 수 있어요. 단군의 건국 이야기와 8조법으로 고조선 사회의 모습을 짐작할 수 있어요. 고조선의 성장과 멸망 과정을 순서대로 말할 수 있어요. 부여·고구려·옥저·동예·삼한의 정치와 풍습을 비교할 수 있…","keywords":["군장","고인돌","비파형 동검","홍익인간","제정일치","8조법","중계 무역","연맹 왕국","제천 행사","소도"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#c0","kind":"concept","title":"청동기 시대의 변화","text":"청동기 시대는 구리에 주석 등을 섞은 청동으로 도구를 만들기 시작한 시대예요. 우리 역사에서는 기원전 2000년경에서 기원전 1500년경 사이에 청동기 문화가 시작되었어요. 이 무렵 일부 지역에서 벼농사가 시작되었고, 곡식의 이삭을 따는 반달 돌칼과 무늬가 없는 민무늬 토기를 썼어요. ","keywords":["군장","고인돌"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#c1","kind":"concept","title":"단군의 건국 이야기와 고조선의 성립","text":"우리 역사에서 처음 세워진 나라는 고조선이에요. 고조선의 건국 이야기는 고려 때 승려 일연이 쓴 『삼국유사』 등에 전해요. 『삼국유사』에는 단군왕검이 기원전 2333년에 고조선을 세웠다고 적혀 있어요. 이야기의 줄거리는 이래요. 하늘을 다스리는 환인의 아들 환웅이 바람·비·구름을 맡은 ","keywords":["홍익인간"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#c2","kind":"concept","title":"고조선의 성장과 8조법","text":"고조선은 중국 랴오닝(요령) 지방과 한반도 서북부를 중심으로 성장했어요. 비파형 동검과 탁자식 고인돌, 미송리식 토기가 함께 나오는 지역을 보면 고조선의 문화 범위를 짐작할 수 있어요. 기원전 4세기 무렵에는 중국의 연나라와 맞설 만큼 강해졌고, 기원전 3세기 무렵에는 부왕·준왕처럼 왕","keywords":["고인돌","비파형 동검","8조법","중계 무역"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#c3","kind":"concept","title":"한과의 전쟁과 고조선의 멸망","text":"위만의 손자 우거왕 때 고조선은 중계 무역으로 큰 이익을 얻으며 세력을 키웠어요. 이를 경계한 중국 한의 무제가 기원전 109년에 대군을 보내 쳐들어왔어요. 고조선은 1년 가까이 버티며 한의 군대를 여러 차례 물리쳤어요. 그러나 싸움이 길어지자 지배층 안에서 항복하자는 세력과 끝까지 싸","keywords":["중계 무역"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#c4","kind":"concept","title":"여러 나라의 성장 ① 부여와 고구려","text":"철기 문화가 널리 퍼지면서 만주와 한반도 곳곳에 여러 나라가 자라났어요. 그중 부여와 고구려는 여러 부족이 모인 연맹 왕국이에요. 왕이 있었지만, 힘센 부족장인 가들이 자기 지역을 따로 다스렸어요. 구분 · 부여 · 고구려 자리 · 만주 쑹화강 유역의 넓은 평야 · 압록강 중류 졸본 지","keywords":["연맹 왕국","제천 행사"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#c5","kind":"concept","title":"여러 나라의 성장 ② 옥저·동예와 삼한","text":"함경도와 강원도 북부의 동해안에는 옥저와 동예가 있었어요. 두 나라에는 왕이 없었고, 읍군·삼로라고 불린 군장이 각 부족을 다스렸어요. 고구려의 압박을 받아 큰 나라로 성장하지 못했어요. 옥저: 해산물과 소금이 풍부했어요. 여자아이를 어릴 때 신랑 집에 데려가 기르다가 어른이 되면 혼인","keywords":["군장","제천 행사"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t0","kind":"term","title":"군장","text":"청동기 시대에 나타난, 부족을 이끌고 다스린 지배자예요. 다른 부족을 정복하며 세력을 넓혔어요.","keywords":["군장"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t1","kind":"term","title":"고인돌","text":"청동기 시대 지배층의 무덤이에요. 큰 덮개돌을 옮기려면 많은 사람이 필요했으므로, 지배자의 힘을 보여 줘요.","keywords":["고인돌"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t2","kind":"term","title":"비파형 동검","text":"악기 비파를 닮은 청동 칼이에요. 고인돌·미송리식 토기와 함께 고조선의 문화 범위를 짐작하게 해 줘요.","keywords":["비파형 동검"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t3","kind":"term","title":"홍익인간","text":"\"널리 인간을 이롭게 한다\"는 뜻이에요. 단군의 건국 이야기에 나오는 고조선의 건국 이념이에요.","keywords":["홍익인간"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t4","kind":"term","title":"제정일치","text":"제사와 정치를 한 사람이 함께 맡는 것이에요. 예: 제사장이면서 임금인 단군왕검","keywords":["제정일치"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t5","kind":"term","title":"8조법","text":"고조선의 법이에요. 세 조항만 전하는데, 생명 존중·농경 사회·사유 재산·신분 차이를 보여 줘요.","keywords":["8조법"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t6","kind":"term","title":"중계 무역","text":"두 지역 사이에서 물건을 이어 주며 이익을 얻는 무역이에요. 위만 왕조의 고조선은 한과 남쪽 여러 나라 사이에서 중계 무역을 했어요.","keywords":["중계 무역"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t7","kind":"term","title":"연맹 왕국","text":"여러 부족이 모여 이룬 나라예요. 왕이 있지만 부족장들이 자기 지역을 따로 다스려 왕의 힘이 약했어요. 예: 부여, 초기 고구려","keywords":["연맹 왕국"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t8","kind":"term","title":"제천 행사","text":"하늘에 제사를 지내며 온 나라 사람이 함께 즐긴 큰 행사예요. 부여의 영고, 고구려의 동맹, 동예의 무천이 있어요.","keywords":["제천 행사"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#t9","kind":"term","title":"소도","text":"삼한에서 제사장인 천군이 다스린 신성한 지역이에요. 죄인이 도망쳐 들어가도 잡아갈 수 없었어요.","keywords":["소도"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#f0","kind":"faq","title":"고조선이 기원전 2333년에 세워진 게 확실해요?","text":"기원전 2333년은 『삼국유사』 같은 역사책에 전하는 건국 이야기에 따른 연도예요. 아주 오래전 일이라 정확한 해를 증명할 자료는 없어요. 그래서 역사학자들은 유물과 여러 기록을 함께 살펴 고조선이 언제, 어디서 성장했는지 연구해요. 교과서에서도 \"『삼국유사』에 따르면\"처럼 기록의 출처를 밝혀 말해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#f1","kind":"faq","title":"곰이 사람이 되었다는 이야기를 왜 역사 시간에 배워요?","text":"건국 이야기는 있는 그대로의 사실이 아니라, 그 시대 사람들의 생각과 사회 모습을 담은 이야기예요. 곰이 여자가 되어 환웅과 혼인한 이야기는 곰을 섬기던 부족이 환웅 세력과 손잡은 일로 풀이해요. 이렇게 이야기 속 상징을 풀어 보면 고조선이 어떻게 세워졌는지 짐작할 수 있어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#f2","kind":"faq","title":"연맹 왕국은 그냥 왕국이랑 뭐가 달라요?","text":"연맹 왕국에도 왕은 있지만, 여러 부족장(가)이 자기 지역을 따로 다스려서 왕의 힘이 약했어요. 부여에서 흉년이 들면 왕에게 책임을 묻기도 한 것이 그 예예요. 다음 단원에서 배우는 삼국은 왕이 부족장들을 신하로 삼고 나라 전체를 직접 다스리는 나라로 바뀌어 가요. 이런 나라를 중앙 집권 국가라고 해요.","keywords":["연맹 왕국"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#f3","kind":"faq","title":"제천 행사는 왜 그렇게 중요했어요?","text":"농사가 잘되려면 날씨가 중요했기 때문에, 사람들은 하늘에 제사를 지내며 풍년을 빌고 감사했어요. 또 여러 부족이 한자리에 모여 함께 먹고 노래하고 춤추면서 한 나라 사람이라는 마음을 다졌어요. 나라의 중요한 일을 의논하거나 죄인을 풀어 주기도 했다는 기록도 있어요.","keywords":["제천 행사"],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#m0","kind":"mistake","title":"자주 하는 실수","text":"영고(부여, 12월)·동맹(고구려, 10월)·무천(동예, 10월)을 헷갈리는 실수 — \"부여–영고, 고구려–동맹, 동예–무천\"으로 나라와 짝지어 기억해요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#m1","kind":"mistake","title":"자주 하는 실수","text":"청동기 시대에 청동 농기구를 썼다고 생각하는 실수 — 청동은 귀해서 무기·거울·방울에 쓰고, 농기구는 반달 돌칼처럼 돌로 만들었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-01#m2","kind":"mistake","title":"자주 하는 실수","text":"삼한의 소도를 제정일치의 예로 드는 실수 — 천군이 제사를 따로 맡았으니 제사와 정치가 나뉜 모습이에요. 제정일치의 예는 단군왕검이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-01","grade":"m3"},
{"id":"hist-m-2-02","kind":"unit","title":"삼국과 가야의 성장과 문화","text":"고구려·백제·신라와 가야가 나라의 틀을 갖추며 성장한 과정과, 이들이 남긴 문화유산과 교류를 살펴봐요. 왕위 세습·율령 반포·불교 수용이 중앙 집권 국가의 표시인 까닭을 설명할 수 있어요. 삼국의 전성기와 한강 유역을 둘러싼 경쟁을 왕의 업적과 함께 순서대로 말할 수 있어요. 가야 연맹의 성장과 쇠퇴 과정을 설명할 수 있어요. 삼국과 가야의 무덤·불교 문…","keywords":["중앙 집권 국가","율령","태학","남진 정책","나제 동맹","광개토 대왕릉비","화랑도","순수비","덩이쇠","돌무지덧널무덤"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#c0","kind":"concept","title":"중앙 집권 국가로의 발전","text":"고구려·백제·신라는 처음에는 여러 부족이 모인 연맹 왕국이었어요. 그러다 왕이 부족장들을 신하로 삼고 나라 전체를 직접 다스리는 중앙 집권 국가로 발전했어요. 중앙 집권 국가로 발전했다는 표시는 크게 세 가지예요. 왕위 세습: 한 집안이 왕위를 이어 가고, 나아가 아버지가 아들에게 왕위","keywords":["중앙 집권 국가","율령"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#c1","kind":"concept","title":"백제와 고구려의 전성기","text":"백제는 4세기 후반 근초고왕 때 전성기를 맞았어요. 남쪽으로 마한의 남은 세력을 정복하고, 북쪽으로 고구려의 평양성을 공격해 고국원왕을 전사시켰어요(371년). 왕위를 아들에게 물려주는 일도 이때 자리 잡았고, 중국의 동진, 바다 건너 왜와도 활발히 교류했어요. 고구려는 5세기에 전성기","keywords":["남진 정책","광개토 대왕릉비"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#c2","kind":"concept","title":"신라의 성장과 한강 유역 쟁탈","text":"고구려의 남진에 맞서 백제와 신라는 433년에 나제 동맹을 맺었어요. 그러나 475년 한성을 빼앗긴 백제는 도읍을 웅진(지금의 공주)으로 옮겼어요. 이후 백제 성왕은 도읍을 다시 사비(지금의 부여)로 옮기고(538년) 나라를 새롭게 일으키려 했어요. 신라는 6세기에 크게 성장했어요. 지","keywords":["율령","나제 동맹","화랑도"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#c3","kind":"concept","title":"가야 연맹의 성장과 쇠퇴","text":"가야는 낙동강 하류의 변한 지역에서 자라난 여러 작은 나라의 연맹이에요. 처음에는 김해의 금관가야가 중심이었어요. 금관가야는 김수로왕이 세웠다고 전해요. 가야는 철이 많이 났어요. 철로 만든 갑옷·무기·농기구가 발달했고, 납작한 쇳덩이인 덩이쇠를 돈처럼 쓰거나 낙랑과 왜에 수출했어요. ","keywords":["중앙 집권 국가","덩이쇠"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#c4","kind":"concept","title":"삼국과 가야의 무덤과 불교 문화유산","text":"무덤 나라 · 대표 무덤 · 특징 고구려 · 돌무지무덤(장군총), 굴식 돌방무덤 · 굴식 돌방무덤의 벽과 천장에 고분 벽화를 그림(무용총의 사냥 그림·춤 그림, 강서대묘의 사신도) 백제 · 돌무지무덤(서울 석촌동), 벽돌무덤(무령왕릉) · 석촌동 무덤은 고구려 무덤과 닮아 백제를 세운 ","keywords":["돌무지덧널무덤"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#c5","kind":"concept","title":"대외 교류와 일본에 전한 문화","text":"삼국과 가야는 중국, 서역(중앙아시아·서아시아), 왜와 활발히 교류했어요. 고구려는 중국 북쪽의 나라들, 북방의 유목 민족과 교류했어요. 백제는 바닷길로 중국 남쪽의 나라들(남조)과 왜를 잇는 교류의 중심이었어요. 신라의 무덤에서는 서역에서 온 것으로 보이는 유리그릇이 나와, 먼 지역과","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t0","kind":"term","title":"중앙 집권 국가","text":"왕이 부족장들을 신하로 삼고 나라 전체를 직접 다스리는 나라예요. 왕위 세습·율령 반포·불교 수용이 그 표시예요.","keywords":["중앙 집권 국가"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t1","kind":"term","title":"율령","text":"나라를 다스리는 법이에요. 율은 형벌에 관한 법, 영은 나라 제도에 관한 법이에요.","keywords":["율령"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t2","kind":"term","title":"태학","text":"고구려 소수림왕이 세운 교육 기관이에요.","keywords":["태학"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t3","kind":"term","title":"남진 정책","text":"고구려 장수왕이 도읍을 평양으로 옮기고 남쪽으로 영토를 넓힌 정책이에요.","keywords":["남진 정책"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t4","kind":"term","title":"나제 동맹","text":"433년에 백제와 신라가 고구려의 남진에 맞서려고 맺은 동맹이에요. 554년 관산성 전투로 깨졌어요.","keywords":["나제 동맹"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t5","kind":"term","title":"광개토 대왕릉비","text":"장수왕이 아버지 광개토 대왕의 업적을 새겨 세운 비석이에요.","keywords":["광개토 대왕릉비"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t6","kind":"term","title":"화랑도","text":"신라의 청소년 단체예요. 진흥왕 때 나라의 조직으로 커져 많은 인재를 길러 냈어요.","keywords":["화랑도"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t7","kind":"term","title":"순수비","text":"왕이 새로 넓힌 땅을 돌아보고 세운 비석이에요. 예: 진흥왕의 북한산 순수비","keywords":["순수비"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t8","kind":"term","title":"덩이쇠","text":"가야에서 만든 납작한 쇳덩이예요. 돈처럼 쓰거나 다른 나라에 수출했어요.","keywords":["덩이쇠"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#t9","kind":"term","title":"돌무지덧널무덤","text":"나무 덧널 위에 돌을 쌓고 흙으로 덮은 신라의 무덤이에요. 도굴이 어려워 금관 같은 껴묻거리가 많이 남았어요.","keywords":["돌무지덧널무덤"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#f0","kind":"faq","title":"불교를 받아들이면 왜 왕의 힘이 세져요?","text":"연맹 왕국 시절에는 부족마다 섬기는 신과 풍습이 달랐어요. 온 나라가 불교라는 하나의 믿음을 갖게 되면 백성의 마음이 하나로 모여요. 또 \"왕이 곧 부처\"라는 생각을 퍼뜨려 왕의 권위를 높이기도 했어요. 그래서 불교 수용은 율령 반포와 함께 중앙 집권 국가로 가는 중요한 단계로 꼽혀요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#f1","kind":"faq","title":"가야도 오랫동안 있었는데 왜 \"삼국 시대\"라고 해요?","text":"가야는 500년 넘게 이어졌지만, 끝까지 여러 작은 나라의 연맹 단계에 머물러 고구려·백제·신라처럼 강한 중앙 집권 국가가 되지 못했어요. 그래서 흔히 삼국 시대라고 불러요. 하지만 가야는 철 생산과 교역, 토기 문화로 이웃 나라와 일본에 큰 영향을 주었어요. 그래서 요즘은 가야를 함께 다루어 \"삼국과 가야\"라고 배워요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#f2","kind":"faq","title":"광개토 대왕과 장수왕은 어떤 사이예요?","text":"장수왕은 광개토 대왕의 아들이에요. 아버지 광개토 대왕은 주로 북쪽의 만주로 영토를 넓혔고, 아들 장수왕은 도읍을 평양으로 옮기고 남쪽으로 내려와 한강 유역을 차지했어요. 장수왕은 아버지의 업적을 기리려고 광개토 대왕릉비를 세웠어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#f3","kind":"faq","title":"신라 무덤에서는 왜 금관 같은 보물이 많이 나와요?","text":"신라의 돌무지덧널무덤은 나무 덧널 위에 돌을 두껍게 쌓고 흙으로 덮어서, 몰래 파고 들어가기가 매우 어려웠어요. 그래서 오랜 세월 동안 도굴을 피해 금관, 금 귀걸이, 천마도 같은 껴묻거리가 그대로 남았어요. 반대로 드나드는 길이 있는 굴식 돌방무덤은 도굴을 많이 당했어요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#m0","kind":"mistake","title":"자주 하는 실수","text":"율령을 반포한 왕을 섞는 실수 — 고구려는 소수림왕, 백제는 고이왕, 신라는 법흥왕이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#m1","kind":"mistake","title":"자주 하는 실수","text":"광개토 대왕과 장수왕의 업적을 바꾸는 실수 — 만주 정복·왜 격퇴는 광개토 대왕, 평양 천도·한성 함락은 아들 장수왕이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-02#m2","kind":"mistake","title":"자주 하는 실수","text":"금관가야와 대가야의 통합 시기를 헷갈리는 실수 — 금관가야는 532년 법흥왕, 대가야는 562년 진흥왕 때 신라에 통합되었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-02","grade":"m3"},
{"id":"hist-m-2-03","kind":"unit","title":"삼국 통일과 발해의 건국","text":"수·당과의 전쟁에서 신라의 삼국 통일까지의 과정과, 발해가 세워진 의미를 동아시아 정세 속에서 살펴봐요. 7세기 동아시아 여러 나라의 관계 속에서 삼국의 전쟁을 설명할 수 있어요. 고구려가 수·당의 침략을 물리친 과정을 말할 수 있어요. 나당 동맹부터 나당 전쟁까지 신라의 삼국 통일 과정을 순서대로 정리하고, 통일의 의의와 한계를 평가할 수 있어요. 발해…","keywords":["살수 대첩","천리장성","안시성 싸움","나당 동맹","부흥 운동","백강 전투","나당 전쟁","매소성 전투","기벌포 전투","남북국 시대"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#c0","kind":"concept","title":"7세기 동아시아의 국제 정세","text":"6세기 말 중국에서는 오랫동안 나뉘어 있던 땅을 수가 통일했어요(589년). 수가 무너진 뒤에는 당이 들어섰어요(618년). 통일된 중국은 주변 나라를 자기 아래에 두려고 했어요. 이 무렵 동아시아 여러 나라는 서로 손을 잡거나 맞서며 복잡하게 얽혔어요. 큰 흐름으로 보면 다음과 같아요","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#c1","kind":"concept","title":"고구려와 수·당의 전쟁","text":"수는 여러 차례 고구려를 침략했어요. 612년 수 양제는 엄청난 대군을 이끌고 쳐들어왔지만, 고구려 장수 을지문덕은 거짓으로 물러나며 적을 지치게 한 뒤 살수(지금의 청천강으로 보는 곳)에서 크게 무찔렀어요. 이것이 살수 대첩이에요. 무리한 전쟁으로 힘을 잃은 수는 얼마 뒤 무너졌어요.","keywords":["살수 대첩","천리장성","안시성 싸움"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#c2","kind":"concept","title":"나당 동맹과 백제·고구려의 멸망","text":"7세기 중엽 백제 의자왕은 신라를 거세게 공격해 대야성 등 40여 성을 빼앗았어요(642년). 위기에 빠진 신라는 고구려에 도움을 청했지만 거절당했어요. 그러자 김춘추가 당으로 건너가 나당 동맹을 맺었어요(648년). 660년 나당 연합군이 백제를 공격했어요. 신라의 김유신이 이끈 군대","keywords":["나당 동맹"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#c3","kind":"concept","title":"백제와 고구려의 부흥 운동","text":"나라가 무너진 뒤에도 백제와 고구려의 유민들은 나라를 되살리려고 싸웠어요. 이것을 부흥 운동이라고 해요. 백제 부흥 운동: 복신과 도침은 주류성을 중심으로, 흑치상지는 임존성을 중심으로 군사를 일으켰어요. 왜에 머물던 왕자 부여풍을 왕으로 맞았고, 왜는 군대를 보내 도왔어요. 그러나 지","keywords":["부흥 운동","백강 전투"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#c4","kind":"concept","title":"나당 전쟁과 신라의 삼국 통일","text":"백제와 고구려가 무너지자 당은 본심을 드러냈어요. 백제의 옛 땅에 웅진 도독부, 고구려의 옛 땅에 안동 도호부를 두고, 신라까지 자기 아래에 두려 했어요. 한반도 전체를 지배하려 한 것이지요. 신라는 고구려 부흥 운동 세력을 돕고 백제의 옛 땅을 되찾으며 당과 맞섰어요. 이것이 나당 전","keywords":["부흥 운동","나당 전쟁","매소성 전투","기벌포 전투"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#c5","kind":"concept","title":"발해의 건국과 고구려 계승","text":"고구려가 멸망한 뒤 당은 고구려 유민의 일부를 요서 지방의 영주로 강제로 옮겼어요. 그러다 거란족의 반란으로 이 지역이 혼란해지자, 고구려의 장수 출신인 대조영이 고구려 유민과 말갈인을 이끌고 동쪽으로 옮겨 갔어요. 대조영은 뒤쫓아 온 당군을 물리치고 동모산에서 나라를 세웠어요(698년","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t0","kind":"term","title":"살수 대첩","text":"612년 고구려 을지문덕이 살수에서 수의 대군을 크게 물리친 싸움이에요.","keywords":["살수 대첩"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t1","kind":"term","title":"천리장성","text":"고구려가 당의 침략에 대비해 국경에 쌓은 긴 성이에요. 연개소문이 쌓는 일을 감독했어요.","keywords":["천리장성"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t2","kind":"term","title":"안시성 싸움","text":"645년 고구려 안시성의 군사와 백성이 당 태종의 대군을 막아 낸 싸움이에요.","keywords":["안시성 싸움"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t3","kind":"term","title":"나당 동맹","text":"648년 신라의 김춘추가 당에 가서 맺은 동맹이에요. 이후 나당 연합군이 백제와 고구려를 무너뜨렸어요.","keywords":["나당 동맹"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t4","kind":"term","title":"부흥 운동","text":"무너진 나라를 다시 일으키려는 운동이에요. 백제(복신·도침·흑치상지)와 고구려(검모잠·안승)의 유민이 일으켰어요.","keywords":["부흥 운동"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t5","kind":"term","title":"백강 전투","text":"663년 백제 부흥군과 왜의 연합군이 나당 연합군에 크게 진 싸움이에요.","keywords":["백강 전투"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t6","kind":"term","title":"나당 전쟁","text":"백제·고구려 멸망 뒤 한반도 전체를 지배하려는 당에 맞서 신라가 벌인 전쟁이에요. 676년 신라가 이겼어요.","keywords":["나당 전쟁"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t7","kind":"term","title":"매소성 전투","text":"675년 신라가 육지에서 당의 대군을 물리친 나당 전쟁의 싸움이에요.","keywords":["매소성 전투"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t8","kind":"term","title":"기벌포 전투","text":"676년 신라가 바다에서 당의 수군을 물리친 나당 전쟁의 싸움이에요. 이 승리로 삼국 통일을 이루었어요.","keywords":["기벌포 전투"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#t9","kind":"term","title":"남북국 시대","text":"남쪽의 통일 신라와 북쪽의 발해가 함께 있던 시대를 이르는 말이에요.","keywords":["남북국 시대"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#f0","kind":"faq","title":"신라가 당의 힘을 빌린 건 잘못한 거 아니에요?","text":"역사가들은 신라의 삼국 통일을 의의와 한계로 나누어 봐요. 외세인 당의 힘을 빌렸고 고구려의 옛 땅 대부분을 잃은 것은 한계예요. 하지만 신라는 당이 한반도 전체를 지배하려 하자 당과 싸워 몰아냈고, 삼국의 문화를 하나로 모아 민족 문화가 발전하는 바탕을 마련했어요. 한 가지 면만 보지 말고 두 면을 함께 생각하는 것이 중요해요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#f1","kind":"faq","title":"을지문덕은 살수 대첩에서 어떻게 이겼어요?","text":"을지문덕은 수의 군대와 정면으로 싸우기보다, 일부러 지는 척 물러나며 적을 고구려 땅 깊숙이 끌어들였어요. 먼 길을 오느라 지치고 먹을 것이 떨어진 수의 군대가 돌아가려고 살수를 건널 때 공격하여 크게 무찔렀어요. 적의 약점을 이용한 지혜로운 작전이었다고 평가해요.","keywords":["살수 대첩"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#f2","kind":"faq","title":"부흥 운동은 왜 다 실패했어요?","text":"당과 신라의 군사력이 강했던 것도 까닭이지만, 부흥 운동을 이끈 지도자들끼리 다툰 것이 큰 까닭이었어요. 백제 부흥 운동은 지도층의 다툼과 663년 백강 전투의 패배로, 고구려 부흥 운동은 지도층 사이의 갈등으로 힘을 잃었어요.","keywords":["부흥 운동"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#f3","kind":"faq","title":"발해에는 말갈 사람이 많았는데 왜 고구려를 이었다고 해요?","text":"발해는 여러 종족이 함께한 나라라서 백성 가운데 말갈 사람이 많았어요. 하지만 나라를 세운 대조영과 지배층의 대부분이 고구려 사람이었어요. 또 발해 왕은 일본에 보낸 문서에서 고구려를 이었다는 뜻을 밝혔고, 무덤과 온돌 같은 문화에도 고구려의 모습이 이어졌어요. 그래서 발해를 고구려를 계승한 나라로 봐요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#m0","kind":"mistake","title":"자주 하는 실수","text":"살수 대첩과 안시성 싸움의 상대를 바꾸는 실수 — 살수 대첩(612년, 을지문덕)은 수, 안시성 싸움(645년)은 당과의 싸움이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#m1","kind":"mistake","title":"자주 하는 실수","text":"고구려가 멸망한 668년을 삼국 통일의 해로 아는 실수 — 그 뒤 나당 전쟁에서 이겨 당 세력을 몰아낸 676년이 통일을 이룬 해예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-03#m2","kind":"mistake","title":"자주 하는 실수","text":"발해를 말갈인만의 나라로 아는 실수 — 대조영과 지배층은 주로 고구려 사람이었고, 발해는 스스로 고구려를 이었다고 밝혔어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-03","grade":"m3"},
{"id":"hist-m-2-04","kind":"unit","title":"통일 신라와 발해의 발전","text":"통일 신라와 발해가 나라의 제도를 갖추고 변해 간 모습과, 두 나라가 꽃피운 문화와 교류를 알아봐요. 신문왕의 개혁과 9주 5소경으로 통일 신라의 왕권 강화와 통치 체제를 설명할 수 있어요. 발해의 발전 과정과 3성 6부 등 통치 체제를 설명할 수 있어요. 신라 말의 혼란 속에서 호족·6두품이 성장하고 후삼국이 성립한 과정을 말할 수 있어요. 통일 신라와…","keywords":["녹읍","관료전","국학","9주 5소경","3성 6부","해동성국","호족","6두품","화엄 사상","청해진"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#c0","kind":"concept","title":"통일 신라의 왕권 강화와 통치 체제","text":"삼국 통일 뒤 신라는 왕의 힘이 크게 강해졌어요. 진골 출신으로 처음 왕이 된 태종 무열왕(김춘추) 이후 그 자손들이 왕위를 이어 갔어요. 신문왕은 왕권을 더욱 굳게 다졌어요. 왕의 장인인 김흠돌이 일으킨 반란을 진압하고, 이를 계기로 힘센 귀족들을 몰아냈어요. 귀족들에게 녹읍(그 땅의","keywords":["녹읍","관료전","국학"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#c1","kind":"concept","title":"발해의 발전과 통치 체제","text":"발해는 8~9세기에 크게 발전했어요. 왕 · 한 일 무왕 · 영토를 넓히고, 장문휴를 보내 당의 산둥 지방을 공격했어요(732년). 일본과도 국교를 맺었어요. 문왕 · 당과 친하게 지내며 당의 제도와 문물을 받아들였어요. 도읍을 상경으로 옮기고 나라의 제도를 정비했어요. 선왕 · 9세기","keywords":["3성 6부","해동성국"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#c2","kind":"concept","title":"신라 말의 혼란과 후삼국의 성립","text":"8세기 후반부터 신라에서는 진골 귀족들이 왕위를 두고 다투었어요. 약 150년 동안 왕이 20명이나 바뀔 만큼 정치가 어지러웠어요. 중앙이 흔들리자 지방을 제대로 다스리지 못했고, 귀족들의 수탈과 무거운 세금에 시달린 농민들이 곳곳에서 봉기했어요. 진성 여왕 때 일어난 원종과 애노의 난","keywords":["호족","6두품"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#c3","kind":"concept","title":"통일 신라의 불교문화","text":"통일 신라에서는 불교가 크게 발전하여 귀족부터 백성까지 널리 믿었어요. 원효와 의상은 통일 신라 불교를 대표하는 승려예요. 원효 · 의상 여러 불교 이론의 다툼을 하나로 아우르려고 했어요. · 당에 유학하고 돌아와 화엄 사상을 널리 폈어요. \"나무아미타불\"만 정성껏 외워도 극락에 갈 수","keywords":["화엄 사상"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#c4","kind":"concept","title":"고구려·당·말갈 문화가 어우러진 발해 문화","text":"발해 문화는 고구려 문화를 바탕으로 당 문화를 받아들이고, 백성 가운데 많았던 말갈 사람들의 문화까지 함께 어우러졌어요. 이어받은 문화 · 발해의 문화유산 고구려 · 집의 온돌, 굴식 돌방무덤에 모줄임 천장을 한 정혜 공주 묘, 고구려와 닮은 연꽃무늬 기와 당 · 당의 도읍 장안성을 본","keywords":["3성 6부"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#c5","kind":"concept","title":"활발한 대외 교류","text":"통일 신라의 교류 통일 신라는 당과 활발히 교류했어요. 많은 유학생과 승려가 당으로 건너갔고, 당의 산둥 반도 등지에는 신라 사람이 모여 사는 신라방, 이들을 관리하는 신라소, 신라 사람이 세운 절인 신라원이 생겼어요. 울산항은 국제 무역항으로 이름나 아라비아 상인까지 드나들었어요. 9","keywords":["청해진"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t0","kind":"term","title":"녹읍","text":"귀족이 그 땅에서 세금을 거두고 백성의 노동력까지 부릴 수 있게 한 땅이에요. 신문왕이 없앴어요.","keywords":["녹읍"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t1","kind":"term","title":"관료전","text":"관리에게 준 땅으로, 세금만 거둘 수 있었어요. 신문왕이 녹읍 대신 주었어요.","keywords":["관료전"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t2","kind":"term","title":"국학","text":"신문왕이 세운 유학 교육 기관이에요. 왕에게 충성하는 관리를 기르려 했어요.","keywords":["국학"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t3","kind":"term","title":"9주 5소경","text":"통일 신라의 지방 제도예요. 전국을 9주로 나누고 중요한 곳에 작은 도읍인 5소경을 두었어요.","keywords":["9주 5소경"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t4","kind":"term","title":"3성 6부","text":"발해의 중앙 정치 조직이에요. 당의 제도를 받아들였지만 정당성을 중심으로 발해에 맞게 운영했어요.","keywords":["3성 6부"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t5","kind":"term","title":"해동성국","text":"\"바다 동쪽의 번성한 나라\"라는 뜻으로, 9세기 전반 선왕 때 전성기를 맞은 발해를 중국에서 부른 이름이에요.","keywords":["해동성국"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t6","kind":"term","title":"호족","text":"신라 말 지방에서 스스로 성주·장군이라 부르며 군사력과 경제력을 키운 세력이에요.","keywords":["호족"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t7","kind":"term","title":"6두품","text":"신라 골품제의 신분으로, 능력이 있어도 높은 관직에 오를 수 없었어요. 신라 말 개혁을 주장하거나 호족과 손잡았어요.","keywords":["6두품"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t8","kind":"term","title":"화엄 사상","text":"모든 것이 서로 의지하며 조화를 이룬다는 불교 사상이에요. 의상이 신라에 널리 폈어요.","keywords":["화엄 사상"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#t9","kind":"term","title":"청해진","text":"장보고가 828년 완도에 설치한 해상 기지예요. 해적을 몰아내고 해상 무역의 중심이 되었어요.","keywords":["청해진"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#f0","kind":"faq","title":"녹읍이랑 관료전은 둘 다 땅인데 뭐가 그렇게 달라요?","text":"둘 다 관리나 귀족에게 준 땅이지만, 그 땅에서 가질 수 있는 권리가 달랐어요. 녹읍을 받으면 세금을 거둘 뿐 아니라 그 땅의 백성에게 일까지 시킬 수 있었어요. 관료전에서는 세금만 거둘 수 있었어요. 백성의 노동력을 부릴 수 있으면 개인 군대처럼 쓸 수도 있으니, 녹읍을 없앤 것은 귀족의 힘을 크게 줄인 개혁이었어요.","keywords":["녹읍","관료전"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#f1","kind":"faq","title":"발해는 왜 해동성국이라고 불렸어요?","text":"\"해동\"은 바다의 동쪽, \"성국\"은 번성한 나라라는 뜻이에요. 9세기 전반 선왕 때 발해가 가장 넓은 영토를 차지하고 제도와 문화도 크게 발전하자, 중국에서 발해를 이렇게 높여 불렀어요.","keywords":["해동성국"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#f2","kind":"faq","title":"최치원은 왜 신라에서 뜻을 펼치지 못했어요?","text":"최치원은 6두품 출신이에요. 어린 나이에 당에 유학해 과거에 합격할 만큼 뛰어났지만, 신라에서는 골품제 때문에 높은 관직에 오를 수 없었어요. 진성 여왕에게 나라를 바로잡을 개혁안을 올렸지만, 진골 귀족들이 받아들이지 않았어요. 이처럼 능력보다 신분을 따지는 골품제는 신라 말 6두품이 불만을 품은 까닭이 되었어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#f3","kind":"faq","title":"석굴암이랑 불국사는 같은 거예요?","text":"아니에요. 둘 다 경주 토함산에 있고 경덕왕 때 김대성이 짓기 시작했다고 전해 함께 이야기하지만, 서로 다른 유산이에요. 불국사는 여러 건물과 석가탑·다보탑이 있는 절이고, 석굴암은 돌을 다듬어 쌓아 만든 인공 석굴 안에 본존불을 모신 곳이에요.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#m0","kind":"mistake","title":"자주 하는 실수","text":"녹읍과 관료전을 거꾸로 아는 실수 — 노동력까지 부릴 수 있던 것은 녹읍이고, 신문왕은 녹읍을 없애고 세금만 거두는 관료전을 주었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#m1","kind":"mistake","title":"자주 하는 실수","text":"원효와 의상의 활동을 바꾸는 실수 — 아미타 신앙·불교 대중화는 원효, 당 유학·화엄 사상·부석사는 의상이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-04#m2","kind":"mistake","title":"자주 하는 실수","text":"후백제와 후고구려를 세운 사람을 바꾸는 실수 — 후백제는 견훤(900년, 완산주), 후고구려는 궁예(901년, 송악)예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-04","grade":"m3"},
{"id":"hist-m-2-05","kind":"unit","title":"고려의 성립과 대외 관계","text":"고려가 후삼국을 통일하고 나라의 틀을 세운 과정, 문벌 귀족과 무신 정권으로 이어진 정치의 변화, 거란·여진·몽골과의 관계를 배워요. 태조 왕건이 후삼국을 통일한 과정과 호족 통합·북진 정책을 설명할 수 있어요. 광종과 성종이 왕권을 강화하고 통치 제도를 정비한 내용을 말할 수 있어요. 문벌 귀족 사회가 흔들리고 무신 정권이 들어선 과정, 백성들이 봉기한…","keywords":["호족","북진 정책","노비안검법","과거제","문벌 귀족","음서","무신 정변","강동 6주","별무반","삼별초"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#c0","kind":"concept","title":"후삼국 통일과 태조 왕건의 정책","text":"신라 말 지방에서 성장한 호족 가운데 견훤은 후백제(900년), 궁예는 후고구려(901년)를 세웠어요. 신라·후백제·후고구려가 맞선 이 시기를 후삼국 시대라고 해요. 궁예의 신하였던 왕건은 918년에 고려를 세웠어요. 이름부터 고구려를 잇는다는 뜻이에요. 고려는 935년 신라의 항복을 ","keywords":["호족","북진 정책"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#c1","kind":"concept","title":"광종·성종의 체제 정비","text":"태조가 죽은 뒤 호족 출신 공신들의 힘이 커져 왕권이 흔들렸어요. 광종은 왕권을 강하게 만들었어요. 노비안검법(956년): 원래 양인이었는데 억울하게 노비가 된 사람을 조사해 양인으로 되돌렸어요. 호족이 거느린 노비가 줄어 호족의 경제력과 군사력이 약해지고, 세금을 내는 양인은 늘었어요","keywords":["호족","노비안검법","과거제"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#c2","kind":"concept","title":"문벌 귀족 사회와 그 동요","text":"나라가 안정되자 여러 대에 걸쳐 높은 관리를 낸 가문이 문벌 귀족이 되었어요. 이들은 과거와 음서(공신이나 높은 관리의 자손을 시험 없이 관리로 뽑는 제도)로 관직을 차지하고, 왕실과 혼인하며 권력을 키웠어요. 이자겸의 난(1126년): 왕실과 겹겹이 혼인한 이자겸이 권력을 휘두르다 왕","keywords":["문벌 귀족","음서"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#c3","kind":"concept","title":"무신 정변과 백성의 봉기","text":"고려는 문신을 우대해서 무신은 높은 벼슬에 오르기 어려웠고, 군대의 지휘권도 문신이 맡는 일이 많았어요. 쌓인 불만이 터져 1170년 의종 때 정중부·이의방 등이 무신 정변을 일으켜 정권을 잡았어요. 무신들끼리 권력 다툼이 이어지다 1196년 최충헌이 권력을 잡았어요. 이후 최씨 집안이","keywords":["무신 정변"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#c4","kind":"concept","title":"거란·여진과의 관계","text":"고려는 고구려를 잇는다며 북진 정책을 폈고, 발해를 멸망시킨 거란을 멀리하고 송과 가까이 지냈어요. 그러자 거란이 세 차례 쳐들어왔어요. 침입 · 고려의 대응 1차(993년) · 서희가 거란 장수 소손녕과 외교 담판을 벌여 전쟁 없이 강동 6주(압록강 동쪽 땅)를 얻음 2차(1010년)","keywords":["북진 정책","강동 6주","별무반"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#c5","kind":"concept","title":"몽골의 침입과 항쟁","text":"13세기에 몽골이 큰 제국을 세웠어요. 고려에 왔던 몽골 사신이 돌아가는 길에 죽은 일을 구실로 몽골은 1231년부터 여러 차례 고려에 쳐들어왔어요. 강화도 천도(1232년): 최씨 무신 정권의 최우는 수도를 강화도로 옮겨 오래 버티려 했어요. 몽골군은 바다 싸움에 약했기 때문이에요. ","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t0","kind":"term","title":"호족","text":"신라 말 지방에서 성을 쌓고 군대를 거느리며 그 지역을 다스린 세력이에요. 고려를 세운 왕건도 호족 출신이에요.","keywords":["호족"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t1","kind":"term","title":"북진 정책","text":"고구려를 계승한다는 생각으로 서경(평양)을 중시하고 북쪽으로 영토를 넓히려 한 고려의 정책이에요.","keywords":["북진 정책"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t2","kind":"term","title":"노비안검법","text":"광종이 실시한 법으로, 억울하게 노비가 된 사람을 조사해 다시 양인으로 되돌렸어요. 호족의 힘을 약하게 만들었어요.","keywords":["노비안검법"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t3","kind":"term","title":"과거제","text":"시험으로 관리를 뽑는 제도예요. 고려에서는 광종 때(958년) 쌍기의 건의로 처음 실시했어요.","keywords":["과거제"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t4","kind":"term","title":"문벌 귀족","text":"여러 대에 걸쳐 높은 관리를 내고 왕실과 혼인하며 권력을 누린 고려 전기의 지배층이에요. 예: 경원 이씨(이자겸 집안)","keywords":["문벌 귀족"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t5","kind":"term","title":"음서","text":"공신이나 높은 관리의 자손을 과거 시험 없이 관리로 뽑는 제도예요. 문벌 귀족이 권력을 이어 가는 바탕이 되었어요.","keywords":["음서"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t6","kind":"term","title":"무신 정변","text":"1170년 문신 중심의 정치에 불만을 품은 무신들이 일으킨 정변이에요. 이후 약 100년 동안 무신이 권력을 잡았어요.","keywords":["무신 정변"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t7","kind":"term","title":"강동 6주","text":"993년 서희가 거란과의 외교 담판으로 얻은 압록강 동쪽의 땅이에요.","keywords":["강동 6주"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t8","kind":"term","title":"별무반","text":"윤관의 건의로 만든 군대로, 여진의 기병에 맞서려고 기병(신기군)을 중심으로 보병과 승병까지 모았어요.","keywords":["별무반"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#t9","kind":"term","title":"삼별초","text":"최씨 무신 정권 때 만들어진 군사 조직이에요. 개경 환도에 반대해 진도와 제주도에서 1273년까지 몽골과 싸웠어요.","keywords":["삼별초"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#f0","kind":"faq","title":"윤관이 힘들게 쌓은 동북 9성을 왜 돌려줬어요?","text":"동북 9성은 넓은 지역에 흩어져 있어 지키기가 매우 어려웠고, 여진이 계속 공격하면서 땅을 돌려 달라고 간절히 요청했어요. 여진은 돌려주면 다시는 침범하지 않고 조공을 바치겠다고 약속했지요. 고려 조정은 전쟁 부담을 줄이려고 1109년 9성을 돌려주었어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#f1","kind":"faq","title":"왕건은 왜 부인이 그렇게 많았어요?","text":"왕건에게는 29명의 부인이 있었어요. 각 지방의 힘센 호족과 혼인으로 가족 관계를 맺어, 호족들이 고려에 등을 돌리지 않게 하려는 정책이었어요. 하지만 왕건이 죽은 뒤에는 왕자들의 외가인 호족들이 서로 다투어 왕권이 흔들리기도 했어요. 그래서 광종이 왕권 강화에 힘썼지요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#f2","kind":"faq","title":"무신 정변은 왜 일어났어요?","text":"고려는 문신을 우대해서 무신은 높은 벼슬에 오르기 어려웠고, 전쟁 때도 지휘는 문신이 맡는 일이 많았어요. 의종 때 무신과 군인들이 차별과 푸대접을 받는 일이 거듭되자, 1170년 정중부·이의방 등이 들고일어나 문신들을 몰아내고 권력을 잡았어요.","keywords":["무신 정변"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#m0","kind":"mistake","title":"자주 하는 실수","text":"서희·강감찬·윤관을 헷갈리는 실수 — 서희는 말(외교 담판)로 강동 6주, 강감찬은 귀주 대첩(거란), 윤관은 별무반으로 여진을 정벌해 동북 9성이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#m1","kind":"mistake","title":"자주 하는 실수","text":"노비안검법을 \"모든 노비를 풀어 준 법\"으로 아는 실수 — 억울하게 노비가 된 사람만 조사해 양인으로 되돌린 법이에요. 노비 제도 자체는 그대로 있었어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-05#m2","kind":"mistake","title":"자주 하는 실수","text":"강화도 천도(몽골)와 서경 천도 운동(묘청)을 섞는 실수 — 강화도 천도는 1232년 몽골과의 전쟁 때 실제로 옮긴 것이고, 서경 천도는 1135년 무렵 묘청이 주장했지만 이루어지지 않았어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-05","grade":"m3"},
{"id":"hist-m-2-06","kind":"unit","title":"원 간섭기와 고려의 문화","text":"원의 간섭을 받으며 달라진 고려 사회와 공민왕의 개혁, 고려 사람들이 남긴 문화유산과 활발한 대외 교류, 고려 사람들의 생활을 살펴봐요. 원 간섭기에 고려의 정치와 사회가 어떻게 달라졌는지 설명할 수 있어요. 공민왕의 개혁 내용과 신진 사대부·신흥 무인 세력이 성장한 과정을 말할 수 있어요. 고려의 불교·유학과 대표 문화유산(상감 청자, 팔만대장경, 『직…","keywords":["부마국","정동행성","권문세족","몽골풍","전민변정도감","신진 사대부","성리학","상감 기법","벽란도","향도"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#c0","kind":"concept","title":"원 간섭기 고려의 변화","text":"몽골과 강화를 맺은 뒤 고려는 나라를 유지했지만, 약 80년 동안 원(몽골이 세운 나라)의 간섭을 받았어요. 이 시기를 원 간섭기라고 해요. 달라진 점 · 내용 부마국 · 고려 왕은 원의 공주와 혼인해 원 황제의 사위(부마)가 되었어요. 왕의 이름에 원에 충성한다는 뜻의 \"충\" 자가 붙","keywords":["부마국","정동행성"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#c1","kind":"concept","title":"공민왕의 개혁과 새로운 세력의 성장","text":"14세기 중엽 원이 약해지고 중국에서 명이 일어나자, 공민왕은 원의 간섭에서 벗어나려고 개혁을 펼쳤어요. 반원 자주 정책 원의 힘을 믿고 권세를 부리던 기철 등 친원 세력을 없앴어요. 정동행성의 기구(이문소)를 없애고, 원의 간섭으로 바뀐 관제를 되돌렸어요. 쌍성총관부를 공격해 철령 이","keywords":["정동행성","권문세족","몽골풍","전민변정도감"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#c2","kind":"concept","title":"고려의 불교와 유학","text":"고려는 불교를 나라의 종교로 받들었고, 나라를 다스리는 이념으로는 유학을 중시했어요. 불교 — 교종과 선종을 하나로 고려 불교에는 경전 공부를 중시하는 교종과 참선(마음 수행)을 중시하는 선종이 있었어요. 승려 · 시기 · 한 일 의천 · 고려 전기 · 왕자 출신. 교종을 중심으로 선종","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#c3","kind":"concept","title":"고려의 대표 문화유산","text":"상감 청자 고려는 맑은 푸른빛의 청자로 이름났어요. 12세기 무렵에는 고려만의 상감 기법을 개발했어요. 그릇 겉면에 무늬를 새겨 파낸 다음, 그 자리를 흰 흙이나 붉은 흙으로 메우고 유약을 발라 구우면 흰색·검은색 무늬가 나타나요. 팔만대장경 대장경은 불교 경전을 모은 것이에요. 몽골의","keywords":["상감 기법"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#c4","kind":"concept","title":"벽란도와 대외 교류","text":"고려는 여러 나라와 활발하게 교류했어요. 그 중심이 수도 개경 가까이 예성강 어귀에 있던 국제 무역항 벽란도예요. 교류한 나라 · 주고받은 물건 송 (가장 활발) · 고려는 비단·약재·책을 들여오고, 금·은·인삼·종이·먹·나전 칠기·화문석 등을 팔았어요. 거란·여진 · 은·모피·말을 들","keywords":["벽란도"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#c5","kind":"concept","title":"고려 사람들의 생활","text":"고려 사람들의 가족 생활은 조선 후기와 꽤 달랐어요. 아들과 딸을 크게 차별하지 않았거든요. 호적: 아들과 딸을 구분하지 않고 태어난 차례대로 적었어요. 상속: 재산을 아들딸 구별 없이 고르게 나누어 주었어요. 제사: 아들이 없으면 딸이 지내기도 하고, 형제자매가 돌아가며 지내기도 했어","keywords":["향도"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t0","kind":"term","title":"부마국","text":"임금의 사위 나라라는 뜻이에요. 원 간섭기 고려 왕이 원의 공주와 혼인해 원 황제의 사위가 된 것을 가리켜요.","keywords":["부마국"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t1","kind":"term","title":"정동행성","text":"원이 일본을 정벌하려고 고려에 둔 기구예요. 원정이 실패한 뒤에도 남아 고려의 정치에 간섭했어요.","keywords":["정동행성"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t2","kind":"term","title":"권문세족","text":"원 간섭기에 원과 가까운 관계를 이용해 권력을 잡은 고려의 지배층이에요. 높은 벼슬과 넓은 농장을 차지했어요.","keywords":["권문세족"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t3","kind":"term","title":"몽골풍","text":"원 간섭기에 고려에 퍼진 몽골의 풍습이에요. 예: 변발, 족두리, 소주. 반대로 원에 퍼진 고려의 풍습은 고려양이라고 해요.","keywords":["몽골풍"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t4","kind":"term","title":"전민변정도감","text":"공민왕이 신돈을 등용해 둔 기구로, 권문세족이 빼앗은 토지를 주인에게 돌려주고 억울하게 노비가 된 사람을 풀어 주었어요.","keywords":["전민변정도감"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t5","kind":"term","title":"신진 사대부","text":"고려 말 과거를 거쳐 관리가 된 학자 관료들이에요. 성리학을 공부하고 권문세족과 불교의 폐단을 비판했어요. 예: 정몽주, 정도전","keywords":["신진 사대부"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t6","kind":"term","title":"성리학","text":"사람의 본성과 우주의 이치를 탐구하고 일상의 도덕과 예절을 중시하는 새로운 유학이에요. 원 간섭기에 안향이 고려에 들여왔어요.","keywords":["성리학"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t7","kind":"term","title":"상감 기법","text":"그릇 겉면에 무늬를 새겨 파낸 자리에 다른 색 흙을 메워 넣어 무늬를 나타내는 고려만의 도자기 기법이에요.","keywords":["상감 기법"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t8","kind":"term","title":"벽란도","text":"개경 가까이 예성강 어귀에 있던 고려의 국제 무역항이에요. 송·일본·아라비아 상인이 드나들었어요.","keywords":["벽란도"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#t9","kind":"term","title":"향도","text":"불교 신앙으로 모인 무리예요. 매향과 불상·석탑 만들기를 함께 했고, 고려 후기에는 마을 공동체 조직이 되었어요.","keywords":["향도"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#f0","kind":"faq","title":"원 간섭기에도 고려는 나라였어요? 원에 합쳐진 거 아니에요?","text":"원은 정복한 많은 지역을 직접 다스렸지만, 고려는 오랜 항쟁 끝에 강화를 맺어 왕조와 고유한 풍습을 지켰어요. 다만 왕이 원의 사위가 되고 관제가 낮아지는 등 원의 간섭을 많이 받았어요. 그래서 \"원에 합쳐진 시기\"가 아니라 \"원의 간섭을 받은 시기\", 곧 원 간섭기라고 불러요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#f1","kind":"faq","title":"팔만대장경은 나무인데 어떻게 750년 넘게 썩지 않았어요?","text":"경판을 보관하는 해인사 장경판전은 창의 크기와 위치를 달리해 바람이 잘 통하게 하고, 바닥에 숯과 횟가루 등을 깔아 습도를 알맞게 조절하도록 지었어요. 장경판전도 유네스코 세계 유산이에요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#f2","kind":"faq","title":"몽골풍이랑 고려양이 헷갈려요.","text":"어디로 퍼졌는지 보면 돼요. 몽골풍은 몽골의 풍습이 고려로 들어온 것(변발, 족두리, 소주)이고, 고려양은 고려의 풍습이 원으로 건너간 것(고려식 옷, 음식)이에요. \"양(樣)\"은 모양·양식이라는 뜻이라 \"고려 모양\", 곧 고려 스타일이라고 기억하면 쉬워요.","keywords":["몽골풍"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#m0","kind":"mistake","title":"자주 하는 실수","text":"몽골풍과 고려양을 거꾸로 아는 실수 — 몽골풍은 고려에 퍼진 몽골 풍습, 고려양은 원에 퍼진 고려 풍습이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#m1","kind":"mistake","title":"자주 하는 실수","text":"팔만대장경을 금속 활자로 찍은 것으로 아는 실수 — 팔만대장경은 나무판(목판)에 새긴 것이고, 금속 활자로 찍은 책은 『직지심체요절』이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-06#m2","kind":"mistake","title":"자주 하는 실수","text":"권문세족과 신진 사대부를 섞는 실수 — 원과 가까운 세력이 권문세족, 과거로 관리가 되어 성리학을 공부하고 권문세족을 비판한 세력이 신진 사대부예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-06","grade":"m3"},
{"id":"hist-m-2-07","kind":"unit","title":"조선의 건국과 통치 체제","text":"조선이 세워진 과정과 유교를 바탕으로 한 통치 체제, 주변 나라와의 사대교린 외교, 세종 때 꽃핀 훈민정음과 과학 기술, 조선 전기의 문화를 알아봐요. 위화도 회군에서 조선 건국, 한양 천도까지의 과정을 순서대로 설명할 수 있어요. 태종·세종·세조·성종이 나라의 틀을 다진 내용과 『경국대전』의 의미를 말할 수 있어요. 의정부와 6조, 3사, 8도 등 통치…","keywords":["위화도 회군","『경국대전』","의정부","6조","3사","관찰사","사대교린","훈민정음","집현전","분청사기"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#c0","kind":"concept","title":"위화도 회군과 조선 건국","text":"고려 말 명이 철령 이북 땅을 차지하겠다고 알려 오자, 우왕과 최영은 요동 정벌을 결정했어요. 이성계는 \"작은 나라가 큰 나라를 치는 것은 옳지 않다, 여름철 농사철에 군사를 일으키면 안 된다, 왜구가 빈틈을 노린다, 장마철이라 활이 풀리고 병이 돈다\"는 네 가지 까닭(4불가론)을 들어","keywords":["위화도 회군"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#c1","kind":"concept","title":"국왕들의 체제 정비와 『경국대전』","text":"조선 초 왕들은 나라의 기틀을 하나씩 다졌어요. 왕 · 한 일 태종 · 공신과 왕족이 거느린 사병을 없애고, 6조가 왕에게 직접 보고하게 해(6조 직계제) 왕권을 강화했어요. 호패법으로 인구를 파악했어요. 세종 · 집현전을 두어 학자를 길렀어요. 의정부의 재상들이 나랏일을 먼저 의논하게","keywords":["『경국대전』","의정부","6조","훈민정음","집현전"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#c2","kind":"concept","title":"중앙과 지방의 통치 조직, 과거 제도","text":"중앙 의정부: 최고 기관. 영의정·좌의정·우의정(3정승)이 나랏일을 의논했어요. 6조: 실제 업무를 나누어 맡았어요. 6조 · 맡은 일 이조 · 관리의 인사 호조 · 호구·세금·나라 살림 예조 · 의례·외교·교육·과거 병조 · 군사 형조 · 법률·형벌 공조 · 건축·토목·공업 3사: 사","keywords":["의정부","6조","3사","관찰사"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#c3","kind":"concept","title":"사대교린 외교","text":"조선은 주변 나라와 사대교린의 원칙으로 관계를 맺었어요. 사대(큰 나라를 섬김): 명과 사신을 정기적으로 주고받으며 조공을 바치고, 명 황제에게 왕으로 인정받았어요(책봉). 이를 통해 왕권을 안정시키고, 선진 문물을 받아들이며 무역의 이익도 얻었어요. 이웃 큰 나라와 평화를 지키는 실리","keywords":["사대교린"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#c4","kind":"concept","title":"훈민정음 창제와 과학 기술의 발달","text":"훈민정음 세종은 백성이 한자를 몰라 억울한 일을 당해도 글로 뜻을 펴지 못하는 것을 안타깝게 여겼어요. 그래서 1443년 훈민정음(백성을 가르치는 바른 소리)을 만들고, 1446년 반포했어요. 자음은 소리를 낼 때 발음 기관의 모양을 본떠 만들었어요(ㄱ, ㄴ, ㅁ, ㅅ, ㅇ을 바탕으로 ","keywords":["훈민정음"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#c5","kind":"concept","title":"유교 윤리의 보급과 조선 전기 문화","text":"조선은 유교, 그중에서도 성리학을 나라의 기본 이념으로 삼았어요. 그래서 백성의 생활 속에 유교 윤리를 퍼뜨리려 애썼어요. 『삼강행실도』: 세종 때 나라에 충성한 신하, 부모를 잘 모신 자식, 절개를 지킨 여성의 이야기를 모아 그림과 함께 엮은 책이에요. 글을 모르는 백성도 그림을 보고","keywords":["분청사기"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t0","kind":"term","title":"위화도 회군","text":"1388년 요동 정벌에 나섰던 이성계가 압록강의 섬 위화도에서 군대를 되돌려 권력을 잡은 사건이에요.","keywords":["위화도 회군"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t1","kind":"term","title":"『경국대전』","text":"조선의 기본 법전이에요. 세조 때 편찬을 시작해 성종 때 완성·반포했어요.","keywords":["『경국대전』"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t2","kind":"term","title":"의정부","text":"조선의 최고 행정 기관이에요. 영의정·좌의정·우의정이 나랏일을 의논했어요.","keywords":["의정부"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t3","kind":"term","title":"6조","text":"이조·호조·예조·병조·형조·공조로, 나랏일을 나누어 실제로 처리한 조선의 중앙 관청이에요.","keywords":["6조"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t4","kind":"term","title":"3사","text":"사헌부·사간원·홍문관이에요. 관리를 감찰하고 왕에게 바른말을 하며, 권력이 한쪽으로 쏠리지 않게 막았어요.","keywords":["3사"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t5","kind":"term","title":"관찰사","text":"조선의 8도에 하나씩 보낸 지방관으로, 도 안의 수령을 감독했어요.","keywords":["관찰사"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t6","kind":"term","title":"사대교린","text":"명과는 사대(큰 나라를 섬김), 여진·일본과는 교린(이웃과 사귐)을 원칙으로 한 조선의 외교 정책이에요.","keywords":["사대교린"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t7","kind":"term","title":"훈민정음","text":"\"백성을 가르치는 바른 소리\"라는 뜻으로, 세종이 1443년에 만들고 1446년에 반포한 우리 글자예요.","keywords":["훈민정음"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t8","kind":"term","title":"집현전","text":"세종이 둔 학문 연구 기관이에요. 학자들이 정책을 연구하고 책을 펴내며 훈민정음 연구에도 참여했어요.","keywords":["집현전"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#t9","kind":"term","title":"분청사기","text":"회색 흙으로 빚은 그릇에 흰 흙을 발라 꾸민 조선 전기의 도자기예요. 소박하고 자유로운 멋이 있어요.","keywords":["분청사기"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#f0","kind":"faq","title":"왜 수도를 한양으로 옮겼어요?","text":"한양은 나라의 가운데에 있어 전국을 다스리기 좋았고, 한강을 통해 세금으로 걷은 곡식을 배로 실어 나르기 편했어요. 또 북한산 등 산으로 둘러싸여 적을 막기에도 유리했지요. 고려의 옛 세력이 많은 개경을 떠나 새 나라의 분위기를 만들려는 뜻도 있었어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#f1","kind":"faq","title":"사대 외교는 큰 나라에 굴복한 거 아니에요?","text":"사대는 겉으로는 큰 나라를 섬기는 모양이지만, 그 시대 동아시아에서 흔한 외교 방식이었어요. 조선은 명과 평화를 지키며 왕권 안정, 선진 문물, 무역의 이익을 얻었고, 나라 안의 정치는 스스로 결정했어요. 그래서 교과서에서는 사대를 실리적인 외교로 설명해요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#f2","kind":"faq","title":"3사는 왜 중요했어요?","text":"3사(사헌부·사간원·홍문관)는 왕이나 높은 관리가 잘못하면 거리낌 없이 비판했어요. 권력이 한 사람에게 쏠려 함부로 쓰이지 않게 막는 역할이었지요. 오늘날 언론이나 감사 기관이 하는 일과 비슷한 면이 있어요.","keywords":["3사"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#m0","kind":"mistake","title":"자주 하는 실수","text":"『경국대전』을 세종 때 완성했다고 하는 실수 — 『경국대전』은 세조 때 시작, 성종 때 완성이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#m1","kind":"mistake","title":"자주 하는 실수","text":"측우기·앙부일구·자격루를 헷갈리는 실수 — 측우기는 비의 양, 앙부일구는 해 그림자로 시각, 자격루는 물로 움직이는 자동 시계예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-07#m2","kind":"mistake","title":"자주 하는 실수","text":"사대와 교린의 대상을 거꾸로 아는 실수 — 명은 사대, 여진·일본은 교린이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-07","grade":"m3"},
{"id":"hist-m-2-08","kind":"unit","title":"사림의 성장과 왜란·호란","text":"사림이 성장하며 성리학적 질서가 퍼져 나간 과정과, 임진왜란·병자호란을 동아시아 정세 속에서 살펴봐요. 훈구와 사림의 차이, 사화가 일어난 까닭과 붕당이 생긴 과정을 설명할 수 있어요. 서원과 향약이 성리학적 질서를 지방에 퍼뜨린 역할을 말할 수 있어요. 임진왜란의 전개 과정과 수군·의병·명의 지원이 한 역할을 설명할 수 있어요. 광해군의 중립 외교, 인…","keywords":["훈구","사림","사화","붕당","서원","향약","의병","중립 외교","인조반정","주화론"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#c0","kind":"concept","title":"훈구와 사림, 사화의 발생","text":"조선 초에 나라를 세우고 세조의 즉위를 도운 공신들은 높은 벼슬과 넓은 토지를 차지했어요. 이들을 훈구라고 해요. 한편 지방에서 성리학을 깊이 공부하며 제자를 기르던 학자들이 있었어요. 고려 말 정몽주·길재의 학문을 이은 이들을 사림이라고 해요. 성종은 훈구를 견제하려고 김종직 등 사림","keywords":["훈구","사림","사화"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#c1","kind":"concept","title":"사림의 집권과 붕당의 형성","text":"여러 차례 사화를 겪고도 사림은 지방의 서원과 향약을 바탕으로 힘을 길렀어요. 그리고 선조 때에 이르러 정치의 중심을 차지했어요. 그런데 사림 안에서 생각이 갈렸어요. 관리 인사를 맡은 중요한 자리인 이조 전랑에 누구를 앉힐지를 두고, 1575년 무렵 동인과 서인으로 나뉘었어요. 동인은","keywords":["사림","사화","붕당","서원","향약"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#c2","kind":"concept","title":"서원과 향약 — 성리학적 질서의 확산","text":"사림은 지방에서 서원과 향약을 통해 성리학의 가르침을 퍼뜨리고 자기 세력을 키웠어요. 서원 서원은 훌륭한 유학자의 제사를 지내고 학생을 가르치던 사립 교육 기관이에요. 1543년 주세붕이 세운 백운동 서원이 처음이에요. 뒤에 이황의 건의로 임금이 \"소수 서원\"이라는 이름을 새긴 현판을 ","keywords":["사림","서원","향약"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#c3","kind":"concept","title":"임진왜란의 전개와 극복","text":"일본을 통일한 도요토미 히데요시는 1592년 대군을 보내 조선을 침략했어요. 이것이 임진왜란이에요. 전쟁 초기 일본군은 부산진과 동래성을 무너뜨리고 빠르게 북쪽으로 올라왔어요. 충주에서 신립의 군대가 패하자 선조는 의주로 피란했고, 일본군은 20일 만에 한양을 차지했어요. 반격 — 수군","keywords":["의병"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#c4","kind":"concept","title":"광해군의 중립 외교와 두 차례의 호란","text":"광해군의 전후 복구와 중립 외교 임진왜란 뒤 왕이 된 광해군은 전쟁으로 망가진 나라를 다시 세우려고 토지 대장과 호적을 정리하고, 경기도에서 대동법을 실시했어요. 허준은 의학책 『동의보감』을 완성했어요. 그 무렵 만주에서 여진이 후금을 세우고(1616년) 명과 맞섰어요. 명이 군대를 보","keywords":["중립 외교","인조반정"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#c5","kind":"concept","title":"두 전쟁이 동아시아에 끼친 영향","text":"임진왜란과 병자호란은 조선만의 전쟁이 아니라 동아시아 전체를 바꾼 전쟁이었어요. 나라 · 변화 조선 · 인구가 크게 줄고 농토가 황폐해졌어요. 토지 대장과 호적이 사라져 나라 살림이 어려워졌고, 경복궁·불국사 같은 많은 문화유산이 불탔어요. 훈련도감을 두는 등 군사 제도를 고쳤어요. 명","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t0","kind":"term","title":"훈구","text":"조선 초 나라를 세우고 세조의 즉위를 도와 공신이 된 세력이에요. 높은 벼슬과 넓은 토지를 차지했어요.","keywords":["훈구"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t1","kind":"term","title":"사림","text":"지방에서 성리학을 공부하며 제자를 기른 학자들이에요. 성종 때부터 중앙에 진출해 훈구를 비판했어요.","keywords":["사림"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t2","kind":"term","title":"사화","text":"\"선비(사림)가 화를 입었다\"는 뜻으로, 훈구와의 갈등 속에서 사림이 큰 피해를 입은 사건이에요. 무오·갑자·기묘·을사사화가 있어요.","keywords":["사화"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t3","kind":"term","title":"붕당","text":"학문과 정치적 생각을 함께하는 사람들의 무리예요. 선조 때 사림이 동인과 서인으로 나뉘며 생겼어요.","keywords":["붕당"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t4","kind":"term","title":"서원","text":"훌륭한 유학자의 제사를 지내고 학생을 가르친 사립 교육 기관이에요. 최초의 서원은 백운동 서원이에요.","keywords":["서원"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t5","kind":"term","title":"향약","text":"마을 사람들이 서로 돕고 바르게 살기 위해 만든 마을의 자치 규약이에요. 덕업상권·과실상규·예속상교·환난상휼을 내세웠어요.","keywords":["향약"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t6","kind":"term","title":"의병","text":"나라가 위급할 때 나라의 명령 없이 스스로 일어나 싸운 군대예요. 임진왜란 때 곽재우·고경명·조헌 등이 이끌었어요.","keywords":["의병"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t7","kind":"term","title":"중립 외교","text":"광해군이 명과 후금 사이에서 어느 한쪽에 치우치지 않고 전쟁을 피하려 한 외교예요.","keywords":["중립 외교"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t8","kind":"term","title":"인조반정","text":"1623년 서인이 광해군을 몰아내고 인조를 왕으로 세운 사건이에요.","keywords":["인조반정"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#t9","kind":"term","title":"주화론","text":"병자호란 무렵 청과 화해해 나라와 백성을 지키자는 주장이에요. 최명길이 대표적이에요. 끝까지 싸우자는 주장은 주전론이라고 해요.","keywords":["주화론"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#f0","kind":"faq","title":"사화랑 붕당은 뭐가 달라요?","text":"사화는 훈구와 사림이 맞서는 과정에서 사림이 큰 피해를 입은 사건이에요(연산군~명종 때). 붕당은 사림이 정권을 잡은 뒤(선조 때) 사림끼리 생각이 갈려 생긴 무리예요. 사화는 \"사림이 당한 사건\", 붕당은 \"사림 안에서 나뉜 무리\"라고 기억하면 쉬워요.","keywords":["사화","붕당"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#f1","kind":"faq","title":"광해군은 나라를 잘 지키려 했는데 왜 쫓겨났어요?","text":"광해군은 전쟁 뒤 나라를 다시 세우고 중립 외교로 전쟁을 피하려 했어요. 하지만 서인은 광해군이 임진왜란 때 도와준 명의 은혜를 저버렸고, 왕실의 어른과 형제에게 도리를 지키지 않았다고 비판했어요. 결국 1623년 서인이 인조반정을 일으켜 광해군을 몰아냈어요. 광해군을 어떻게 평가할지는 지금도 여러 의견이 있어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#f2","kind":"faq","title":"정묘호란이랑 병자호란이 자꾸 헷갈려요.","text":"순서와 결과로 구분해요. 정묘호란(1627년)은 먼저 일어났고, 인조가 강화도로 피란했으며 형제 관계로 끝났어요. 병자호란(1636년)은 뒤에 일어났고, 인조가 남한산성에서 버티다 항복해 군신 관계를 맺었어요. 상대도 후금에서 청으로 이름이 바뀌었어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#m0","kind":"mistake","title":"자주 하는 실수","text":"사화의 순서를 헷갈리는 실수 — 무오(1498년) → 갑자(1504년) → 기묘(1519년) → 을사(1545년), 앞 글자만 따서 \"무·갑·기·을\"로 외워요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#m1","kind":"mistake","title":"자주 하는 실수","text":"정묘호란과 병자호란의 결과를 바꿔 아는 실수 — 정묘호란은 형제 관계(강화도), 병자호란은 군신 관계(남한산성)예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-08#m2","kind":"mistake","title":"자주 하는 실수","text":"한산도 대첩과 명량 해전을 섞는 실수 — 한산도 대첩은 1592년 학익진, 명량 해전은 1597년 정유재란 때 13척으로 거둔 승리예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-08","grade":"m3"},
{"id":"hist-m-2-09","kind":"unit","title":"조선 후기의 정치 변동","text":"왜란과 호란 뒤 조선이 나라를 다시 정비한 노력과, 붕당 정치에서 탕평 정치로 이어진 변화를 배워요. 전쟁 뒤 비변사가 강해지고 5군영이 생긴 까닭을 설명할 수 있어요. 영정법·대동법·균역법이 각각 무엇을 어떻게 바꾸었는지 구별할 수 있어요. 예송과 환국을 거쳐 영조·정조의 탕평 정치가 나온 흐름을 설명할 수 있어요. 북벌 운동과 통신사 파견으로 조선 후…","keywords":["비변사","5군영","훈련도감","영정법","대동법","공인","균역법","예송","환국","탕평책"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#c0","kind":"concept","title":"전쟁 뒤 통치 체제를 다시 세우다","text":"임진왜란(1592년)과 병자호란(1636년)을 겪으면서 조선은 큰 피해를 입었어요. 전쟁을 치르는 동안 나라를 움직이는 방식도 바뀌었지요. 비변사는 원래 16세기에 국경의 군사 문제를 의논하려고 만든 기구였어요. 전쟁 중에는 군사뿐 아니라 외교·재정·인사까지 나라의 중요한 일을 모두 이","keywords":["비변사","5군영","훈련도감"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#c1","kind":"concept","title":"세금 제도를 고치다 — 영정법·대동법·균역법","text":"조선의 백성은 크게 세 가지 부담을 졌어요. 땅에 매기는 전세, 집집마다 지역 특산물을 바치는 공납, 군대에 가거나 대신 옷감(군포)을 내는 군역이에요. 전쟁으로 땅이 황폐해지고 백성의 삶이 어려워지자 나라는 이 세 가지를 차례로 고쳤어요. 제도 · 무엇을 고쳤나 · 내용 영정법 (인조","keywords":["영정법","대동법","균역법"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#c2","kind":"concept","title":"붕당 정치의 변화 — 예송과 환국","text":"붕당은 학문적·정치적 생각이 같은 양반 관리들의 무리예요. 선조 때 동인과 서인으로 나뉘었고, 동인은 다시 남인과 북인으로 나뉘었어요. 인조반정(1623년) 뒤에는 서인이 주도하고 남인이 함께 참여하며 서로 견제하고 비판하는 붕당 정치가 이루어졌어요. 예송은 현종 때 왕실의 상복을 얼마","keywords":["예송","환국"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#c3","kind":"concept","title":"영조의 탕평 정치","text":"탕평은 \"어느 쪽에도 치우치지 않는다\"는 뜻이에요. 붕당 사이의 다툼이 너무 심해지자 왕이 직접 나서서 붕당 사이의 균형을 잡고 왕의 힘을 키우려 한 정치가 탕평 정치예요. 영조는 붕당을 가리지 않고 탕평에 찬성하는 사람들(탕평파)을 고루 등용했어요. 성균관 앞에 탕평비를 세워 탕평의 ","keywords":["균역법"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#c4","kind":"concept","title":"정조의 탕평 정치와 개혁","text":"영조의 손자 정조는 탕평 정치를 이어 가면서 더 적극적으로 개혁을 펼쳤어요. 붕당의 옳고 그름을 따져 능력 있는 인재를 고루 썼지요. 규장각: 왕실 도서관이면서 학문과 정책을 연구하는 기관이에요. 정조는 이곳에서 젊은 인재를 길러 개혁의 중심으로 삼았고, 차별받던 서얼 출신의 학자(박제","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#c5","kind":"concept","title":"청·일본과의 관계 — 북벌 운동과 통신사","text":"병자호란에서 청에게 항복한 뒤 조선에서는 청에 대한 반감이 컸어요. 청에 인질로 끌려갔다 돌아와 왕이 된 효종은 송시열 등과 함께 청을 치자는 북벌 운동을 추진했어요. 군대를 키우고 성을 고쳤지만, 청의 힘이 강해지고 효종이 일찍 세상을 떠나면서 실제로 청을 정벌하지는 못했어요. 오히려","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t0","kind":"term","title":"비변사","text":"원래 국경의 군사 문제를 의논하던 기구예요. 임진왜란 뒤 나랏일 전반을 다루는 최고 기구가 되었어요.","keywords":["비변사"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t1","kind":"term","title":"5군영","text":"조선 후기 수도와 그 둘레를 지킨 다섯 군영이에요. 훈련도감·어영청·총융청·수어청·금위영으로, 숙종 때 갖추어졌어요.","keywords":["5군영"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t2","kind":"term","title":"훈련도감","text":"임진왜란 중에 만든 군영으로, 포수·사수·살수를 길렀어요. 군인들이 급료를 받는 직업 군인이었어요.","keywords":["훈련도감"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t3","kind":"term","title":"영정법","text":"인조 때 만든 전세 제도로, 풍년·흉년과 관계없이 토지 1결당 쌀 4~6두를 내게 했어요.","keywords":["영정법"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t4","kind":"term","title":"대동법","text":"공납을 특산물 대신 토지의 넓이에 따라 쌀·옷감·동전으로 내게 한 제도예요. 광해군 때 경기도에서 처음 실시했어요.","keywords":["대동법"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t5","kind":"term","title":"공인","text":"대동법 실시 뒤 관청에 필요한 물건을 사서 대 주던 상인이에요.","keywords":["공인"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t6","kind":"term","title":"균역법","text":"영조 때 1년에 내던 군포를 2필에서 1필로 줄인 제도예요.","keywords":["균역법"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t7","kind":"term","title":"예송","text":"현종 때 왕실의 상복을 입는 기간을 두고 서인과 남인이 벌인 두 차례의 논쟁이에요.","keywords":["예송"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t8","kind":"term","title":"환국","text":"숙종 때 왕이 집권 붕당을 한꺼번에 바꾼 일이에요. 붕당 사이의 다툼이 더 심해졌어요.","keywords":["환국"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#t9","kind":"term","title":"탕평책","text":"어느 붕당에도 치우치지 않고 인재를 고루 쓰려던 정책이에요. 영조와 정조가 펼쳤어요.","keywords":["탕평책"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#f0","kind":"faq","title":"붕당은 나쁜 거예요?","text":"처음부터 나쁜 것은 아니었어요. 붕당은 생각이 다른 무리가 서로의 잘못을 비판하고 견제하면서 나랏일을 의논하는 구조였어요. 문제는 숙종 때 환국이 거듭되면서 상대를 견제하는 것이 아니라 아예 몰아내려는 다툼으로 변한 것이에요. 그래서 영조와 정조가 탕평 정치로 바로잡으려 했어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#f1","kind":"faq","title":"대동법은 좋은 제도인데 왜 전국으로 퍼지는 데 100년이나 걸렸어요?","text":"대동법은 땅이 많을수록 많이 내는 제도라서, 땅을 많이 가진 양반 지주들의 부담이 커졌어요. 이들이 거세게 반대했기 때문에 광해군 때 경기도에서 시작한 뒤 지역을 조금씩 넓혀 숙종 때에야 전국 대부분으로 확대되었어요.","keywords":["대동법"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#f2","kind":"faq","title":"탕평이라는 말은 무슨 뜻이에요?","text":"중국의 옛 책 『서경』에 나오는 \"왕의 길은 탕탕평평하다(넓고 평평하다)\"는 말에서 왔어요. 어느 한쪽에 치우치지 않고 공평하다는 뜻이에요. 그래서 붕당에 치우치지 않고 인재를 고루 쓰는 정책을 탕평책이라고 해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#m0","kind":"mistake","title":"자주 하는 실수","text":"영정법·대동법·균역법을 헷갈리는 실수 — 무엇을 고쳤는지로 구별해요. 영정법은 전세(땅), 대동법은 공납(특산물), 균역법은 군역(군포)이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-09#m1","kind":"mistake","title":"자주 하는 실수","text":"탕평비(영조)와 규장각·수원 화성(정조)을 거꾸로 짝짓는 실수 — 할아버지 영조가 탕평의 뜻을 알리고 균역법을 실시했고, 손자 정조가 규장각·장용영·화성으로 개혁을 넓혔어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-09","grade":"m3"},
{"id":"hist-m-2-10","kind":"unit","title":"조선 후기 문화와 사회 변화","text":"실학과 서민 문화가 퍼진 조선 후기의 모습과, 세도 정치 아래 커진 사회 모순에 맞선 여러 세력의 대응을 알아봐요. 농업·상업의 발달이 신분제를 어떻게 흔들었는지 설명할 수 있어요. 농업 중심 개혁론과 상공업 중심 개혁론(북학)을 구별하고, 서학·동학이 퍼진 까닭을 말할 수 있어요. 한글 소설·판소리·탈놀이·풍속화·민화 같은 서민 문화의 특징을 설명할 수…","keywords":["모내기법","공명첩","실학","북학파","동학","판소리","풍속화","세도 정치","삼정의 문란","척화비"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#c0","kind":"concept","title":"농업·상업의 발달과 흔들리는 신분제","text":"조선 후기에는 논에 직접 씨를 뿌리는 대신 모판에서 기른 모를 옮겨 심는 모내기법(이앙법)이 전국으로 퍼졌어요. 잡초를 뽑는 일손이 크게 줄어 한 사람이 더 넓은 땅을 농사지을 수 있게 되었고(광작), 벼를 거둔 논에 보리를 심는 벼·보리 이모작도 널리 이루어졌어요. 인삼·담배·면화처럼","keywords":["모내기법"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#c1","kind":"concept","title":"실학 — 현실을 바꾸려는 새로운 학문","text":"조선 후기 일부 학자들은 성리학이 백성의 어려운 삶을 해결하지 못한다고 보고, 실제 생활에 도움이 되는 학문을 연구했어요. 이를 실학이라고 해요. 갈래 · 주장 · 대표 학자 농업 중심 개혁론 · 토지 제도를 고쳐 농민이 자기 땅을 갖게 하자(자영농 육성) · 유형원, 이익, 정약용 상","keywords":["실학","북학파"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#c2","kind":"concept","title":"서학과 천주교, 그리고 동학","text":"17세기 무렵 청에 다녀온 사신들을 통해 서양의 학문과 과학 기술, 천주교 서적이 들어왔어요. 이를 서학이라고 해요. 처음에는 학문으로 연구되다가, 18세기 후반에는 일부 학자들이 천주교를 신앙으로 받아들였어요. 천주교는 \"모든 사람은 하느님 앞에서 평등하다\"고 가르쳐 신분 차별에 시달","keywords":["동학","세도 정치"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#c3","kind":"concept","title":"서민 문화의 발달","text":"경제가 성장하고 서당 교육이 퍼지면서 서민들도 문화를 즐기고 만들게 되었어요. 서민 문화에는 솔직한 감정 표현과 양반 사회에 대한 풍자가 잘 드러나요. 한글 소설: 『홍길동전』, 『춘향전』, 『심청전』 등. 신분 차별과 탐관오리를 비판하는 내용이 많았어요. 판소리: 소리꾼 한 사람이 북","keywords":["판소리","풍속화"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#c4","kind":"concept","title":"세도 정치와 삼정의 문란, 농민 봉기","text":"1800년 정조가 세상을 떠나고 어린 순조가 왕위에 오르자, 왕비의 집안 같은 몇몇 가문이 권력을 독차지했어요. 이를 세도 정치라고 해요. 순조·헌종·철종 3대, 약 60년 동안 이어졌어요. 세도 정치 아래에서는 관직을 돈으로 사고파는 일이 흔했어요. 돈을 주고 관리가 된 사람들은 본전","keywords":["세도 정치","삼정의 문란"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#c5","kind":"concept","title":"흥선 대원군의 개혁과 통상 수교 거부","text":"1863년 어린 고종이 왕위에 오르자 아버지 흥선 대원군이 실제 권력을 잡았어요. 그는 세도 정치로 무너진 왕권을 다시 세우고 백성의 불만을 줄이려 했어요. 나라 안의 개혁 세도 가문을 몰아내고 인재를 고루 등용, 비변사의 기능을 줄이고 의정부를 다시 세움 붕당의 근거지이자 백성을 괴롭","keywords":["세도 정치"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t0","kind":"term","title":"모내기법","text":"모판에서 기른 모를 논에 옮겨 심는 농사 방법이에요. 이앙법이라고도 해요. 조선 후기에 전국으로 퍼졌어요.","keywords":["모내기법"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t1","kind":"term","title":"공명첩","text":"받는 사람의 이름 칸을 비워 둔 관직 임명장이에요. 나라가 재정을 마련하려고 팔았고, 신분제가 흔들리는 원인이 되었어요.","keywords":["공명첩"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t2","kind":"term","title":"실학","text":"조선 후기에 백성의 생활에 실제로 도움이 되는 개혁을 연구한 학문이에요.","keywords":["실학"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t3","kind":"term","title":"북학파","text":"청의 앞선 문물을 배우고 상공업을 키우자고 주장한 실학자들이에요. 홍대용, 박지원, 박제가 등이 있어요.","keywords":["북학파"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t4","kind":"term","title":"동학","text":"1860년 최제우가 만든 종교예요. \"사람이 곧 하늘\"이라며 모든 사람의 평등을 가르쳤어요.","keywords":["동학"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t5","kind":"term","title":"판소리","text":"소리꾼이 고수의 북장단에 맞춰 노래·말·몸짓으로 긴 이야기를 들려주는 공연이에요.","keywords":["판소리"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t6","kind":"term","title":"풍속화","text":"사람들의 일상생활을 그린 그림이에요. 김홍도와 신윤복이 대표적인 화가예요.","keywords":["풍속화"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t7","kind":"term","title":"세도 정치","text":"정조가 세상을 떠난 뒤 몇몇 가문이 권력을 독차지한 정치예요. 순조·헌종·철종 때 약 60년 이어졌어요.","keywords":["세도 정치"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t8","kind":"term","title":"삼정의 문란","text":"전정·군정·환곡이 세도 정치 시기에 크게 어지러워져 백성을 괴롭힌 일이에요.","keywords":["삼정의 문란"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#t9","kind":"term","title":"척화비","text":"흥선 대원군이 서양과 교류하지 않겠다는 뜻으로 1871년 전국에 세운 비석이에요.","keywords":["척화비"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#f0","kind":"faq","title":"실학자들의 주장은 실제로 나라 정책에 쓰였어요?","text":"대부분은 크게 반영되지 못했어요. 실학자 중에는 권력에서 밀려난 사람이 많았고, 세도 정치가 시작되면서 개혁이 어려워졌기 때문이에요. 하지만 실학의 생각은 사라지지 않았어요. 특히 북학파의 생각은 박지원의 손자 박규수 등을 거쳐 뒷날 개화사상으로 이어졌어요.","keywords":["실학"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#f1","kind":"faq","title":"천주교와 동학은 둘 다 평등을 말했는데 왜 정부가 탄압했어요?","text":"조선은 신분 질서와 유교 예법을 바탕으로 한 나라였어요. \"모든 사람이 평등하다\"는 가르침은 이 질서를 흔드는 것으로 보였지요. 천주교는 조상 제사를 거부한 일로, 동학은 세상을 어지럽힌다는 이유로 탄압받았어요. 그래도 두 종교는 힘든 백성 사이에서 계속 퍼졌어요.","keywords":["동학"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#f2","kind":"faq","title":"흥선 대원군은 왜 서양과 교류하지 않으려 했어요?","text":"그 무렵 청이 서양과의 전쟁(아편 전쟁 등)에서 지고 불리한 조약을 맺는 것을 보고 서양을 크게 경계했어요. 또 서양 배들이 나타나 통상을 요구하고, 병인양요·신미양요처럼 무력으로 쳐들어오자 나라를 지키려면 막아야 한다고 생각했어요. 이 정책은 침략을 일시적으로 막았지만, 서양 문물을 받아들일 시기를 늦추었다는 평가도 함께 받아요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#m0","kind":"mistake","title":"자주 하는 실수","text":"병인양요와 신미양요를 헷갈리는 실수 — 병인양요(1866년)는 프랑스, 신미양요(1871년)는 미국이에요. 순서는 \"병인 → 신미\", 나라는 \"프 → 미\"로 기억해요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#m1","kind":"mistake","title":"자주 하는 실수","text":"홍경래의 난과 임술 농민 봉기를 헷갈리는 실수 — 홍경래의 난은 1811년 평안도, 임술 농민 봉기는 1862년 진주에서 시작해 전국으로 퍼졌어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-10#m2","kind":"mistake","title":"자주 하는 실수","text":"동학을 서양에서 들어온 종교로 착각하는 실수 — 서양에서 들어온 것은 서학(천주교)이고, 동학은 그에 맞서 최제우가 만든 종교예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-10","grade":"m3"},
{"id":"hist-m-2-11","kind":"unit","title":"근대 국가 수립과 민족 운동","text":"개항 이후 근대 국가를 세우려던 여러 노력과, 나라를 빼앗긴 뒤 세계의 흐름 속에서 펼친 민족 운동을 살펴봐요. 강화도 조약 이후 개화 정책을 둘러싼 갈등(임오군란·갑신정변)을 설명할 수 있어요. 동학 농민 운동·갑오개혁·독립 협회·대한 제국이 꿈꾼 나라의 모습을 비교할 수 있어요. 일제의 국권 침탈 과정과 그에 맞선 의병 운동·애국 계몽 운동을 설명할 …","keywords":["강화도 조약","갑신정변","집강소","갑오개혁","독립 협회","대한 제국","을사늑약","의병","3·1 운동","대한민국 임시 정부"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#c0","kind":"concept","title":"개항과 개화 정책을 둘러싼 갈등","text":"1875년 일본은 군함 운요호를 강화도 앞바다에 보내 충돌을 일으키고, 이를 구실로 조약을 강요했어요. 그래서 1876년 맺은 것이 강화도 조약(조일 수호 조규)이에요. 우리나라가 맺은 최초의 근대적 조약이지만, 부산 외에 두 항구를 더 열고, 일본이 조선 해안을 마음대로 측량하고, 조","keywords":["강화도 조약"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#c1","kind":"concept","title":"동학 농민 운동과 갑오개혁","text":"1894년 전라도 고부 군수의 수탈에 맞서 전봉준이 이끄는 농민들이 봉기했어요. 이것이 동학 농민 운동의 시작이에요. 농민군은 \"나쁜 관리를 몰아내고 백성을 구한다\", \"외세를 몰아낸다\"를 내세워 관군을 이기고 전주성을 차지했어요. 정부가 청에 군대를 요청하자 일본군도 들어왔어요. 외국","keywords":["집강소","갑오개혁"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#c2","kind":"concept","title":"독립 협회와 대한 제국","text":"1895년 일본이 명성 황후를 시해하는 사건(을미사변)이 일어나자, 고종은 이듬해 러시아 공사관으로 거처를 옮겼어요(아관 파천). 나라의 자주성이 크게 흔들렸지요. 이때 서재필 등은 독립신문을 펴내고 독립 협회(1896년)를 만들었어요. 독립 협회는 청의 사신을 맞던 영은문 자리에 독립","keywords":["독립 협회","대한 제국"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#c3","kind":"concept","title":"국권 침탈과 의병 운동·애국 계몽 운동","text":"러일 전쟁(1904~1905년)에서 이긴 일본은 대한 제국을 차례로 빼앗아 갔어요. 해 · 조약·사건 · 빼앗긴 것 1905년 · 을사늑약 · 외교권 — 통감부를 두고 내정까지 간섭 1907년 · 고종 강제 퇴위, 한일 신협약 · 일본인 차관이 행정을 맡음, 군대 해산 1910년 · 한","keywords":["대한 제국","을사늑약","의병"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#c4","kind":"concept","title":"식민 통치와 3·1 운동, 대한민국 임시 정부","text":"나라를 빼앗은 일제는 조선 총독부를 두고 식민 통치를 했어요. 통치 방식은 시기마다 바뀌었어요. 시기 · 통치 방식 · 모습 1910년대 · 무단 통치 · 헌병 경찰이 일반 치안까지 맡고, 관리·교사도 칼을 찼어요. 토지 조사 사업으로 많은 농민이 땅을 잃었어요 1920년대 · 문화 통","keywords":["3·1 운동","대한민국 임시 정부"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#c5","kind":"concept","title":"국내외 민족 운동과 8·15 광복","text":"나라 안팎에서 여러 방법으로 독립운동이 이어졌어요. 실력 양성 운동: 우리 물건을 쓰자는 물산 장려 운동, 우리 손으로 대학을 세우자는 민립 대학 설립 운동, 글을 모르는 사람에게 한글을 가르친 문맹 퇴치 운동이 펼쳐졌어요. 무장 독립 전쟁: 1920년 홍범도의 대한 독립군 등이 봉오동","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t0","kind":"term","title":"강화도 조약","text":"1876년 일본과 맺은 조약으로, 우리나라 최초의 근대적 조약이자 불평등 조약이에요.","keywords":["강화도 조약"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t1","kind":"term","title":"갑신정변","text":"1884년 김옥균 등 급진 개화파가 빠른 근대화를 위해 일으킨 정변이에요. 청군의 개입으로 3일 만에 실패했어요.","keywords":["갑신정변"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t2","kind":"term","title":"집강소","text":"동학 농민군이 전주 화약 뒤 전라도 각 고을에 두고 개혁을 실천한 기구예요.","keywords":["집강소"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t3","kind":"term","title":"갑오개혁","text":"1894년 과거제와 신분제를 없애는 등 정치·사회 제도를 근대적으로 바꾼 개혁이에요.","keywords":["갑오개혁"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t4","kind":"term","title":"독립 협회","text":"1896년 서재필 등이 만든 단체로, 독립문을 세우고 만민 공동회를 열어 자주독립과 국민의 권리를 주장했어요.","keywords":["독립 협회"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t5","kind":"term","title":"대한 제국","text":"1897년 고종이 황제에 오르며 바꾼 나라 이름이에요. 광무개혁을 펼쳤어요.","keywords":["대한 제국"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t6","kind":"term","title":"을사늑약","text":"1905년 일본이 강제로 맺어 대한 제국의 외교권을 빼앗은 조약이에요. 통감부가 설치되었어요.","keywords":["을사늑약"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t7","kind":"term","title":"의병","text":"나라가 위험할 때 스스로 일어나 싸운 백성의 군대예요. 1907년에는 해산된 군인들도 합류했어요.","keywords":["의병"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t8","kind":"term","title":"3·1 운동","text":"1919년 3월 1일 시작되어 전국과 해외로 퍼진 독립 만세 운동이에요.","keywords":["3·1 운동"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#t9","kind":"term","title":"대한민국 임시 정부","text":"3·1 운동 뒤 1919년 상하이에 세워진 정부로, 처음으로 민주 공화제를 채택했어요.","keywords":["대한민국 임시 정부"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#f0","kind":"faq","title":"을사조약을 왜 \"을사늑약\"이라고 불러요?","text":"\"늑약\"은 억지로 맺은 조약이라는 뜻이에요. 일본은 군대로 궁궐을 둘러싸고 대신들을 위협해 조약을 맺었고, 고종 황제는 끝까지 이 조약을 인정하지 않았어요. 그래서 정당한 조약이 아니라는 뜻으로 을사늑약이라고 불러요.","keywords":["을사늑약"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#f1","kind":"faq","title":"임시 정부는 왜 우리나라가 아니라 중국 상하이에 세웠어요?","text":"나라 안에서는 일제의 감시가 심해서 정부를 세우고 활동하기 어려웠어요. 상하이에는 외국인이 다스리는 지역(조계)이 있어 일제의 손길이 비교적 덜 미쳤고, 교통이 편리해 여러 나라와 연락하기도 좋았어요. 그래서 상하이에 대한민국 임시 정부를 세웠어요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#f2","kind":"faq","title":"독립운동은 싸우는 것만 했어요?","text":"아니에요. 무기를 들고 싸운 무장 독립 전쟁뿐 아니라, 우리 물건을 쓰는 물산 장려 운동, 한글을 가르친 문맹 퇴치 운동, 우리말과 역사를 지킨 민족 문화 수호 운동, 외교 활동까지 여러 방법이 있었어요. 모두 나라를 되찾으려는 노력이었어요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#m0","kind":"mistake","title":"자주 하는 실수","text":"임오군란과 갑신정변을 헷갈리는 실수 — 임오군란(1882년)은 차별받은 구식 군인들, 갑신정변(1884년)은 김옥균 등 급진 개화파가 일으켰어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#m1","kind":"mistake","title":"자주 하는 실수","text":"이봉창과 윤봉길의 의거 장소를 바꾸어 기억하는 실수 — 이봉창은 도쿄(일왕), 윤봉길은 상하이 훙커우 공원이에요. 둘 다 1932년, 한인 애국단 단원이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-11#m2","kind":"mistake","title":"자주 하는 실수","text":"신민회와 신간회를 헷갈리는 실수 — 신민회(1907년)는 나라를 빼앗기기 전 애국 계몽 단체, 신간회(1927년)는 생각이 다른 민족 운동가들이 힘을 합친 단체예요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-11","grade":"m3"},
{"id":"hist-m-2-12","kind":"unit","title":"민주주의 발전과 우리의 과제","text":"대한민국 정부 수립 이후 민주주의와 경제가 성장해 온 과정과, 통일·평화·환경 등 지속가능한 사회를 위한 과제를 생각해 봐요. 대한민국 정부가 세워진 과정과 6·25 전쟁의 전개·영향을 설명할 수 있어요. 4·19 혁명, 5·18 민주화 운동, 6월 민주 항쟁의 원인·전개·의미를 비교할 수 있어요. 경제 성장이 가져온 사회 변화(산업화·노동 문제·도시화)…","keywords":["5·10 총선거","제헌 국회","6·25 전쟁","정전 협정","4·19 혁명","5·18 민주화 운동","6월 민주 항쟁","경제 개발 5개년 계획","이촌향도","6·15 남북 공동 선언"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#c0","kind":"concept","title":"대한민국 정부 수립","text":"1945년 광복 뒤 한반도는 북위 38도선을 경계로 남쪽에는 미군, 북쪽에는 소련군이 들어왔어요. 연합국은 한반도에 임시 정부를 세우는 문제를 논의했지만 미국과 소련의 의견이 맞지 않았어요. 문제가 국제 연합(유엔)으로 넘어가자 유엔은 한반도 전체에서 인구 비례에 따른 총선거를 하기로 ","keywords":["5·10 총선거","제헌 국회"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#c1","kind":"concept","title":"6·25 전쟁","text":"1950년 6월 25일 북한군이 38도선을 넘어 기습적으로 남쪽을 침략했어요. 이것이 6·25 전쟁이에요. 북한군은 사흘 만에 서울을 차지하고 낙동강 근처까지 내려왔어요. 국군은 낙동강 방어선에서 힘겹게 버텼어요. 유엔은 북한의 침략을 막으려고 유엔군을 보냈어요. 1950년 9월 인천 ","keywords":["6·25 전쟁","정전 협정"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#c2","kind":"concept","title":"4·19 혁명과 5·18 민주화 운동","text":"대한민국은 헌법으로 민주 공화국을 세웠지만, 민주주의가 자리 잡기까지는 시민들의 많은 희생과 노력이 필요했어요. 4·19 혁명(1960년): 이승만 정부는 헌법을 고쳐 가며 오랫동안 권력을 유지했어요. 1960년 3월 15일 정부와 여당이 대통령·부통령 선거에서 큰 부정을 저지르자(3·","keywords":["4·19 혁명","5·18 민주화 운동"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#c3","kind":"concept","title":"6월 민주 항쟁과 민주주의의 발전","text":"1980년대 신군부 정부 아래에서 국민들은 대통령을 직접 뽑는 제도(직선제)로 헌법을 바꾸자고 요구했어요. 그런데 1987년 대학생 박종철이 경찰의 고문으로 숨진 사실이 알려지고, 정부가 헌법을 바꾸지 않겠다고 발표하자(4·13 호헌 조치) 국민의 분노가 커졌어요. 시위에 나선 대학생 ","keywords":["6월 민주 항쟁"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#c4","kind":"concept","title":"경제 성장과 사회 변화","text":"6·25 전쟁 뒤 우리나라는 매우 가난했고 외국의 원조에 많이 기대었어요. 1960년대부터 정부는 경제 개발 5개년 계획을 세워 경제 성장을 이끌었어요. 시기 · 중심 산업 · 모습 1960년대 · 경공업 · 섬유·신발·가발처럼 노동력이 많이 드는 제품을 만들어 수출 1970년대 · 중","keywords":["6·25 전쟁","경제 개발 5개년 계획"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#c5","kind":"concept","title":"평화·통일과 지속가능한 사회를 위한 과제","text":"분단 뒤 남과 북은 오랫동안 대립했지만, 화해와 협력을 위한 노력도 이어 왔어요. 해 · 남북 관계의 변화 1972년 · 7·4 남북 공동 성명 — 자주·평화·민족적 대단결의 통일 원칙에 처음 합의 1985년 · 분단 뒤 처음으로 이산가족이 고향을 방문해 만남 1991년 · 남북한 유엔","keywords":["6·15 남북 공동 선언"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t0","kind":"term","title":"5·10 총선거","text":"1948년 5월 10일 남한에서 치러진 우리나라 최초의 민주적 보통 선거예요. 제헌 국회 의원을 뽑았어요.","keywords":["5·10 총선거"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t1","kind":"term","title":"제헌 국회","text":"5·10 총선거로 뽑힌 의원들로 이루어져 대한민국 헌법을 만든 국회예요. 헌법은 1948년 7월 17일 공포되었어요.","keywords":["제헌 국회"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t2","kind":"term","title":"6·25 전쟁","text":"1950년 6월 25일 북한의 남침으로 시작되어 1953년 정전 협정으로 멈춘 전쟁이에요.","keywords":["6·25 전쟁"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t3","kind":"term","title":"정전 협정","text":"1953년 7월 27일 맺은, 전쟁의 싸움을 멈추기로 한 약속이에요. 전쟁을 완전히 끝낸 평화 조약은 아니에요.","keywords":["정전 협정"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t4","kind":"term","title":"4·19 혁명","text":"1960년 3·15 부정 선거에 맞서 학생과 시민이 일어나 이승만 정부를 물러나게 한 민주 혁명이에요.","keywords":["4·19 혁명"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t5","kind":"term","title":"5·18 민주화 운동","text":"1980년 5월 광주에서 학생과 시민이 신군부에 맞서 민주주의를 요구한 운동이에요.","keywords":["5·18 민주화 운동"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t6","kind":"term","title":"6월 민주 항쟁","text":"1987년 6월 대통령 직선제를 요구하며 전국에서 일어난 민주화 운동이에요. 그 결과 직선제 헌법이 만들어졌어요.","keywords":["6월 민주 항쟁"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t7","kind":"term","title":"경제 개발 5개년 계획","text":"1960년대부터 정부가 5년 단위로 세운 경제 성장 계획이에요.","keywords":["경제 개발 5개년 계획"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t8","kind":"term","title":"이촌향도","text":"농촌을 떠나 도시로 사람들이 옮겨 가는 현상이에요. 산업화와 함께 크게 늘었어요.","keywords":["이촌향도"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#t9","kind":"term","title":"6·15 남북 공동 선언","text":"2000년 첫 남북 정상 회담 뒤 발표한 선언이에요. 그 뒤 남북 교류가 크게 늘었어요.","keywords":["6·15 남북 공동 선언"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#f0","kind":"faq","title":"정전이랑 종전은 뭐가 달라요?","text":"정전은 싸움을 멈추는 것이고, 종전은 전쟁을 끝내는 것이에요. 6·25 전쟁은 1953년 정전 협정으로 싸움을 멈추었지만, 전쟁을 완전히 끝내는 평화 조약은 아직 맺지 않았어요. 그래서 남과 북 사이에는 지금도 군사 분계선과 비무장 지대가 있어요.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#f1","kind":"faq","title":"민주주의는 이제 다 이루어진 거예요?","text":"민주주의는 한 번 이루면 끝나는 것이 아니에요. 우리나라는 4·19 혁명, 5·18 민주화 운동, 6월 민주 항쟁을 거치며 민주주의를 발전시켰지만, 시민이 관심을 갖고 참여하지 않으면 다시 약해질 수 있어요. 선거에 참여하고, 다른 의견을 존중하고, 거짓 정보를 가려내는 것이 민주주의를 지키는 일이에요.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#f2","kind":"faq","title":"통일은 왜 필요하다고 해요?","text":"통일에 대해서는 여러 생각이 있지만, 교과서에서는 이런 점을 들어요. 이산가족의 아픔을 덜 수 있고, 전쟁의 위험을 줄여 한반도에 평화를 이룰 수 있으며, 분단 때문에 드는 비용을 줄이고 남과 북이 함께 발전할 수 있다는 것이에요. 무엇보다 평화적인 방법으로 차근차근 이루어 가는 것이 중요해요.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#m0","kind":"mistake","title":"자주 하는 실수","text":"4·19 혁명, 5·18 민주화 운동, 6월 민주 항쟁을 헷갈리는 실수 — 4·19 혁명(1960년)은 부정 선거, 5·18 민주화 운동(1980년)은 광주·신군부, 6월 민주 항쟁(1987년)은 직선제 개헌이 핵심이에요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"},
{"id":"hist-m-2-12#m1","kind":"mistake","title":"자주 하는 실수","text":"정전 협정으로 6·25 전쟁이 완전히 끝났다고 생각하는 실수 — 정전 협정은 싸움을 멈춘 약속이에요. 평화 조약은 아직 맺지 않았어요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-m-2","unit":"hist-m-2-12","grade":"m3"}
]);
